window.EPW = {"about":{"title":"About the Week","lede":"One co-hosted programme over four days, bridging the commitments of COP31 and investment-ready projects.","background":["Energy Planning Week 2026 convenes in Bonn two weeks after COP31 closes. Co-hosted by IRENA and GET.transform, it is the first chance for the energy planning community to work out how COP31 commitments become the scenarios, roadmaps and project pipelines needed to deliver them.","The constraint is less the availability of capital than the capacity to direct it: investment follows credible national plans, institutions that sustain them across political cycles, and regional frameworks for shared infrastructure. Planning itself is also changing. Storage, distributed generation and flexibility are reshaping what models must represent, supply-chain and price shocks have undercut pre-2022 assumptions, and climate risk and new methods such as artificial intelligence need to be built in.","The Week brings together three efforts: the Long-term Energy Scenarios (LTES) Network, where government planners strengthen scenario practice; the Global Coalition for Energy Planning (GCEP), which links plans to investment; and GET.transform, a technical assistance programme implemented by GIZ and co-funded by the European Union, Germany, Norway, the Netherlands, Sweden and Austria."],"objectives":["Connect scenario governance, investment signals and implementation, so COP31 commitments become investment-ready projects.","Build the mandates, skills, data and modelling capacity that keep planning on track across political cycles.","Tackle the planning-to-investment bottlenecks raised in LTES and GCEP regional dialogues, such as grids, flexibility, project preparation and finance-facing signals.","Foster peer exchange among planners, financiers, regulators, utilities and partner institutions."],"audience":"Government energy planners and policymakers, alongside industry, finance, regulators, utilities, intergovernmental organisations and the modelling community.","_photo_removed":{"image":"images/scene/forum-plenary.jpg","alt":"Delegates seated around a large open square of tables during a plenary session of the 6th LTES Forum, with presentation screens at the front of the room.","credit":"6th Forum on Long-Term Energy Scenarios, Bonn, November 2025","_note":"Removed from the hero 26 Nov 2026 so the page opens like an app. Rename back to 'photo' to restore."}},"event":{"name":"Energy Planning Week 2026","shortName":"EPW 2026","hostLine":"Co-hosted by IRENA and GET.transform","hosts":[{"name":"IRENA","full":"International Renewable Energy Agency","logo":"images/brand/irena.svg","url":"https://www.irena.org"},{"name":"GET.transform","full":"GET.transform","logo":"images/brand/get-transform.svg","url":"https://www.get-transform.eu","description":"A technical assistance programme implemented by GIZ and co-funded by the European Union, Germany, Norway, the Netherlands, Sweden and Austria.","_descriptionNote":"Standard description requested by GET.transform (Sept 2026) and live on the IRENA event page. Use verbatim; do not revert to the 'several European governments' phrasing."}],"dates":{"start":"2026-12-01","end":"2026-12-04","display":"1–4 December 2026","_datesNote":"1–4 December 2026 is confirmed. Earlier drafts saying 1–3 December or \"three days\" are superseded.","timezone":"Europe/Berlin","timezoneLabel":"CET (UTC+1)"},"venue":{"name":"GIZ Campus Forum","room":"Auditorium","city":"Bonn","country":"Germany","display":"GIZ Campus Forum, Bonn, Germany","address":"Friedrich-Ebert-Allee 32, 53113 Bonn, Germany","mapUrl":"https://www.google.com/maps/search/?api=1&query=GIZ+Campus+Forum,+Friedrich-Ebert-Allee+32,+53113+Bonn,+Germany","capacityNote":"On-site registration is closed. Online registration is open. On-site places are confirmed directly by the co-hosts, with priority for speakers, government planners, and members and partners of the LTES Network, GCEP and GET.transform."},"format":{"type":"Hybrid","note":"Sessions run on-site in Bonn and stream online. All times are CET."},"status":{"phase":"auto","_phaseNote":"The site derives its phase from the programme dates: the opening date before the event, a live now/next strip during it, a closing message after. Nothing to set here.","banner":"Provisional programme. Sessions, speakers and timings are subject to change until the final agenda is published.","showBanner":false},"registration":{"url":"https://forms.cloud.microsoft/r/UhjVrHEPrx","label":"Register to join online","note":""},"join":{"platform":"Microsoft Teams","url":"","_urlNote":"Paste the Teams event link here when it exists. Until it is set, the join buttons show as 'link coming soon' rather than dead links. GDPR: EU-hosted platforms only — no Zoom.","label":"Join online"},"contacts":[{"label":"LTES Network","email":"LTES@irena.org"},{"label":"Global Coalition for Energy Planning","email":"GCEP@irena.org"}],"components":[{"id":"ltes-forum","order":1,"name":"7th International Forum on Long-Term Energy Scenarios","shortName":"LTES Forum","days":"Days 1–2","convener":"IRENA LTES Network","summary":"The seventh edition of IRENA's International Forum on Long-Term Energy Scenarios, convened through the LTES Network. Government planners and scenario practitioners work through electrification after COP31, durable planning ecosystems, data governance, energy security, climate adaptation, artificial intelligence and transformative scenario methods."},{"id":"gcep-dialogue","order":2,"name":"GCEP Planning–Investment Dialogue","shortName":"GCEP Dialogue","days":"Day 3, morning","convener":"Global Coalition for Energy Planning","summary":"Convened under the Global Coalition for Energy Planning. It puts planners in the room with financiers, regulators and utilities to work on the gap between an approved plan and an investable one: what signals finance needs from planning systems, and which bottlenecks recur across the GCEP regional dialogues."},{"id":"implementation","order":3,"name":"Implementation Lab: From Plans to Delivery","shortName":"Implementation Lab","days":"Day 3, afternoon","convener":"GET.transform","summary":"Convened by GET.transform. It follows the plan into delivery, looking at how planning can support enabling energy markets, from policy, regulation and procurement to market design and investment decisions. Country cases show where planning meets the market."},{"id":"partner-sessions","order":4,"name":"Thematic Deep Dives","shortName":"Deep Dives","days":"Day 4","convener":"Partner-hosted sessions","summary":"A morning of thematic deep dives with partners: marine spatial planning, data centres and rising demand, grid infrastructure and flexibility, and regional energy planning."}],"narrative":{"stages":[{"id":"scenarios","label":"Scenarios and planning systems","summary":"The planning systems behind credible long-term scenarios: governance, modelling tools, data, capacity, uncertainty and resilience."},{"id":"policy","label":"Policy translation","summary":"How scenario insights become policies, roadmaps and decisions, through mandates, regulatory pathways, budgeting and coordination."},{"id":"investment","label":"Investment signals and pipelines","summary":"The signals that turn a plan into an investable pipeline, from planning information and sequencing to project preparation and risk allocation."},{"id":"implementation","label":"Implementation and delivery","summary":"What it takes to deliver the plan on the ground: procurement, markets, grids, system operation and institutional accountability."}]}},"faq":{"items":[],"_items_removed":[{"q":"When and where is Energy Planning Week 2026?","a":"1–4 December 2026 at the GIZ Campus Forum, Friedrich-Ebert-Allee 32, 53113 Bonn, Germany. The Week runs in a hybrid format: on site in Bonn and online through Microsoft Teams. All times are CET."},{"q":"Who can attend?","a":"The Week is designed primarily for government energy planners and policymakers, alongside representatives of the energy industry, financial institutions, regulators, utilities, intergovernmental organisations and the scientific and modelling community. Anyone interested is welcome to follow the sessions online."},{"q":"Can I register to attend in Bonn?","a":"On-site registration is closed. Online registration is open. On-site places are confirmed directly by the co-hosts, with priority for speakers, government planners, and members and partners of the LTES Network, GCEP and GET.transform."},{"q":"How do I register?","a":"Complete the {registration form|https://forms.cloud.microsoft/r/UhjVrHEPrx} to join online. Connection details (Microsoft Teams) are shared with registered online participants ahead of the event."},{"q":"How do I get to the venue?","a":"From Bonn Central Station (Bonn Hbf), take underground tram (U-Bahn) line 16 or 63 towards Bad Godesberg, or line 66 towards Bad Honnef, and get off at Ollenhauerstraße. Turn right onto Friedrich-Ebert-Allee and walk towards the city centre; GIZ is on the left. From Cologne Bonn or Frankfurt airport, trains and buses run to Bonn Hbf ({bahn.com|https://www.bahn.com/en}). Local fares are paid by participants."},{"q":"What do I need to bring on the first day?","a":"Registration and badge collection open at 08:00 on Tuesday 1 December at the GIZ Campus. Your badge is needed to enter the venue all week, and you will be asked to sign a photography consent form when you collect it."},{"q":"Are meals provided?","a":"Yes, for registered on-site participants: breakfast, coffee breaks and a vegetarian lunch (with a vegan option) on all four days, a vegetarian welcome dinner on Tuesday 1 December (19:00–21:00, Eventmanufaktur, near Bonn Hbf) and a reception after Day 3. Please send any dietary restrictions to {LTES@irena.org|mailto:LTES@irena.org} as soon as possible."},{"q":"Do I book my own accommodation?","a":"Yes, unless your accommodation is covered by other means. Hotels in the Bundesviertel or near Bonn Hbf give the easiest access to the venue."},{"q":"Can I follow the Week online?","a":"Yes. All plenary and numbered sessions are streamed on Microsoft Teams, except the closed-door LTES Network strategic meeting on Day 3. Connection details are shared with registered online participants ahead of the event."},{"q":"What language are the sessions in?","a":"English only, without interpretation."},{"q":"Who do I contact with questions?","a":"Write to the LTES Network at {LTES@irena.org|mailto:LTES@irena.org}."}]},"gallery":{"show":false,"layout":"pair","credit":"6th Forum on Long-Term Energy Scenarios, Bonn, November 2025","images":[{"id":"forum-group","image":"images/scene/forum-group.jpg","alt":"Participants of the 6th LTES Forum gathered for a group photograph in front of an IRENA backdrop.","span":"wide"},{"id":"forum-dialogue","image":"images/scene/forum-dialogue.jpg","alt":"A participant listening during a working session, with colleagues seated around the table and a presentation on screen behind.","span":"half"}]},"practical":{"documents":[{"title":"Programme","description":"Full agenda with session descriptions and speakers.","url":"https://irena.sharepoint.com/:b:/s/EnergyPlanningCapacityBuilding-ExternalSharing/IQC1TS_dR5qwRYzCbRFIecbbAYqz5nmLP1wgPPVDfg8cFzY?e=MhCEUA","format":"PDF"}],"documentsNote":"Documents are hosted on SharePoint for registered participants. If you have trouble opening them, contact the organisers.","venue":{"name":"GIZ Campus Forum, Auditorium","addressLines":["Friedrich-Ebert-Allee 32"],"_addressNote":"Per logistical note of 13 Nov 2026: all four days at GIZ Campus Forum, Auditorium. Meeting rooms for side meetings and bilaterals on request.","city":"53113 Bonn, Germany","phone":"","mapEmbed":"https://maps.google.com/maps?q=GIZ+Campus+Forum,+Friedrich-Ebert-Allee+32,+53113+Bonn,+Germany&z=16&output=embed"},"gettingThere":["From the airport (Cologne Bonn or Frankfurt): take a train or bus to Bonn Central Station (Bonn Hbf). Tickets are sold at bahn.com/en, in the DB Navigator app, at the DB travel centre or from ticket machines.","From Bonn Hbf: take underground tram (U-Bahn) line 16 or 63 towards Bad Godesberg, or line 66 towards Bad Honnef, and get off at Ollenhauerstraße. Turn right onto Friedrich-Ebert-Allee and walk towards the city centre; GIZ is on the left.","Fares are paid by participants. For a full week, a weekly ticket (Wochenticket) for price level 1b is usually cheapest; the Deutschlandticket is also valid. Paper tickets bought from a machine outside the tram must be stamped.","Hotels in the Bundesviertel or near Bonn Hbf give the easiest access to the venue. Participants book their own accommodation unless it is covered by other means."],"sections":[{"id":"format","heading":"Attending","body":"Energy Planning Week 2026 runs in a hybrid format. On-site registration is closed. Online registration is open. On-site places are confirmed directly by the co-hosts, with priority for speakers, government planners, and members and partners of the LTES Network, GCEP and GET.transform. All plenary and numbered sessions are streamed on Microsoft Teams, except the closed-door LTES Network strategic meeting on Day 3."},{"id":"registration","heading":"Registration and badges","body":"Registration and badge collection open at 08:00 on Tuesday 1 December at the GIZ Campus. Your badge is needed to enter the venue all week. Photographs and video will be taken during the event and may be published by IRENA and GET.transform; participants sign a consent form when collecting their badge."},{"id":"meals","heading":"Meals","body":"Breakfast, coffee breaks and a vegetarian lunch (with a vegan option) are provided free of charge to registered on-site participants on all four days. Registered on-site participants are invited to a vegetarian welcome dinner on Tuesday 1 December, 19:00–21:00, at Eventmanufaktur near Bonn Central Station. A reception follows Day 3 on Thursday 3 December. Please send any dietary restrictions to LTES@irena.org as soon as possible."},{"id":"accessibility","heading":"Access and language","body":"Sessions run in English only, without interpretation. Let the organisers know in advance if you have accessibility requirements."},{"id":"local","heading":"Weather, power and time","body":"Bonn in early December is cold and often wet, typically 0–7 °C: bring a warm coat and an umbrella. Germany uses type C and F plugs (230 V, 50 Hz); bring an adapter if needed. Bonn is on Central European Time (CET, UTC+1)."}],"emergency":[{"number":"112","label":"Emergency services (medical and fire)"},{"number":"110","label":"Police"}]},"programme":{"status":"provisional","days":[{"id":"day-1","label":"Day 1","date":"2026-12-01","weekday":"Tuesday","component":"ltes-forum","theme":"Governing Scenario Work for Delivery","items":[{"start":"08:00","end":"09:00","type":"break","title":"Registration, badge collection and coffee"},{"id":"opening","start":"09:00","end":"09:45","type":"plenary","title":"Welcome remarks and introductory presentations","subtitle":"From COP31 commitments to investment-ready planning","stage":"scenarios","summary":"Welcome remarks from IRENA, GIZ, Germany's Federal Ministry for Economic Cooperation and Development (BMZ) and Federal Ministry for Economic Affairs and Energy (BMWE), Denmark and the Clean Energy Ministerial (CEM).","speakers":[{"name":"Stefanie Bradtner","title":"Communications Manager","org":"GET.transform","role":"Master of Ceremonies"},{"name":"Norela Constantinescu","title":"Deputy Director, IRENA Innovation and Technology Centre","org":"IRENA","role":"Welcome remarks"},{"name":"Vanessa Schmidt","title":"","org":"Federal Ministry for Economic Affairs and Energy (BMWE), Germany","role":"Welcome remarks"},{"name":"Dr. Tania Vorwerk","title":"Deputy Director General, Climate, Environment, Health","org":"Federal Ministry for Economic Cooperation and Development (BMZ), Germany","role":"Welcome remarks"},{"name":"Hanne Jersild","title":"Chief Advisor","org":"Denmark","role":"Welcome remarks"},{"name":"Jean-François Gagné","title":"Head of the CEM Secretariat","org":"Clean Energy Ministerial (CEM)","role":"Welcome remarks"},{"name":"Stefan Mager","title":"Head of Infrastructure – Energy, Water, Mobility","org":"Deutsche Gesellschaft für Internationale Zusammenarbeit (GIZ)","role":"Welcome remarks"}],"speakersStatus":"partial"},{"id":"keynote-d1","start":"09:45","end":"10:25","type":"keynote","title":"Keynote presentation","stage":"scenarios","speakers":[{"name":"Prof. Maarten Hajer","title":"Distinguished Professor of Urban Futures and Futuring; Director, Urban Futures Studio","org":"Utrecht University","role":"Keynote speaker"}],"speakersStatus":"partial"},{"id":"session-1","code":"Session 1","start":"10:25","end":"12:00","type":"session","title":"Electrification and the outcomes of COP31 – what scenarios must now capture","partner":"Co-hosted with UNFCCC","stage":"policy","summary":"This opening session examines what accelerated electrification commitments mean for national energy planning. Government planners and the institutions supporting them discuss how global electrification goals translate into national scenarios, policies and investment pipelines, and what practical support countries need to make that translation work.","speakers":[{"name":"Simon Benmarraze","title":"Head of Strategic Infrastructure Unit","org":"IRENA","role":"Moderator"},{"name":"Dr. Larissa Nogueira","title":"Team Lead, Energy Planning","org":"IRENA","role":"Scene-setting speaker"},{"name":"Dr. Stelios Pesmajoglou","title":"Manager, Mitigation sub-division","org":"UNFCCC","role":"Scene-setting speaker"},{"name":"Luciano Caratori","title":"Global Energy Cluster Lead","org":"Climate Champions Team","role":"Panellist"},{"name":"Dr. Ir. Dadan Kusdiana","title":"Secretary General","org":"National Energy Council (DEN), Indonesia","role":"Panellist"},{"name":"Girvan Pigott","title":"Director of Energy","org":"Ministry of ICTs, Utilities and Energy, Antigua and Barbuda","role":"Panellist"},{"name":"Prof. Dr. Sven Teske","title":"Professor and Research Director, Institute for Sustainable Futures","org":"University of Technology Sydney (UTS), Australia","role":"Panellist"},{"name":"Sarah Rieseberg","title":"Policy Officer","org":"Federal Ministry for the Environment, Climate Action, Nature Conservation and Nuclear Safety (BMUKN), Germany","role":"Panellist"}],"speakersStatus":"partial"},{"start":"12:00","end":"12:30","type":"break","title":"Coffee break"},{"id":"session-2","code":"Session 2","start":"12:30","end":"14:15","type":"session","title":"Building planning ecosystems that survive political cycles","partner":"Co-hosted with the Energy Modelling Hub and Natural Resources Canada","stage":"scenarios","summary":"Durable scenario work depends on institutions. This session examines how countries build planning ecosystems that develop and retain capacity across ministries, universities and research institutions, moving from dependence on external support toward self-sustaining national planning functions. It covers institutional mandates and ownership, skills and retention, modelling-tool institutionalisation, and alignment with policy and budget cycles.","speakers":[{"name":"Brad Little","title":"Deputy Director, Electricity Policy","org":"Natural Resources Canada","role":"Moderator and scene-setting speaker"},{"name":"Edouard Clement","title":"Executive Director","org":"Energy Modelling Hub (EMH)","role":"Scene-setting speaker"},{"name":"Dr. Matías Paredes","title":"Energy Planning and Climate Change Analyst","org":"Ministry of Energy, Chile","role":"Scene-setting speaker and panellist"},{"name":"Alessia De Vita","title":"Advisor","org":"GET.transform","role":"Panellist"},{"name":"Kamil Maqsood","title":"Team Lead – Policy","org":"Power Planning and Monitoring Company (PPMC), Pakistan","role":"Panellist"},{"name":"Dr. Florian Knobloch","title":"Senior Policy Advisor, Scenarios and Economic Aspects of the Energy Transition","org":"Federal Ministry for Economic Affairs and Energy (BMWE), Germany","role":"Panellist"},{"name":"Prof. Leboli Zak Thamae","title":"Coordinator, Energy Research Centre","org":"National University of Lesotho (NUL)","role":"Panellist"}],"speakersStatus":"partial"},{"id":"lunch-d1","start":"14:15","end":"15:45","type":"meal","title":"Lunch break"},{"id":"session-3","code":"Session 3","start":"15:45","end":"17:30","type":"session","title":"Data governance, sharing and quality assurance for developing long-term scenarios","partner":"Co-hosted with European Commission DG ENER","stage":"scenarios","summary":"Credible scenarios rest on credible data, yet many planning teams face fragmented access, persistent gaps and heavy reliance on proprietary datasets. This session examines how countries and regional institutions govern, share and quality-assure energy data – from national energy information systems to regional databases – and explores practical solutions for planning teams with limited resources.","speakers":[{"name":"Dr. Derck Koolen","title":"Energy Policy Economist","org":"European Commission DG ENER","role":"Moderator"},{"name":"Ivo Nacucchio","title":"Data and Modelling Expert","org":"Latin American and Caribbean Energy Organization (OLACDE)","role":"Panellist"},{"name":"Marie Rousselot","title":"Head of Market Intelligence","org":"Enerdata, France","role":"Panellist"},{"name":"Yudiandra Yuwono","title":"Lead Modeller","org":"ASEAN Centre for Energy (ACE)","role":"Panellist"},{"name":"Hanaa Chabini","title":"Head of Observation and Forecasting Department, Directorate of Strategy, Forecasting, Observation and Cooperation","org":"Ministry of Energy Transition and Sustainable Development, Morocco","role":"Panellist"},{"name":"Dr. Joel Yongoua Nana","title":"Senior Manager","org":"Sustainable Energy Africa","role":"Panellist"}],"speakersStatus":"partial"},{"id":"closing-d1","start":"17:30","end":"17:45","type":"plenary","title":"Closing and logistics","speakersStatus":"none"},{"id":"welcome-dinner","start":"19:00","end":"21:00","type":"social","title":"Welcome dinner","speakers":[],"speakersStatus":"none","note":"Eventmanufaktur, Maximilianstraße 15, 53111 Bonn","location":"Eventmanufaktur, Maximilianstraße 15, 53111 Bonn"}]},{"id":"day-2","label":"Day 2","date":"2026-12-02","weekday":"Wednesday","component":"ltes-forum","theme":"Scenarios for Security, Flexibility and Implementation","items":[{"start":"08:00","end":"09:15","type":"break","title":"Coffee and networking"},{"id":"impact-brazil","start":"09:15","end":"10:00","type":"impact","title":"Impact session: Brazil's national energy plan and the LTES Network","stage":"policy","summary":"Brazil's Energy Research Office presents the country's national energy planning instruments, the long-term PNE 2055 and the ten-year expansion plan PDE 2035, and reflects on how peer exchange through the LTES Network informed national planning practice. An impact spotlight on what Network collaboration looks like for national planning processes.","speakers":[{"name":"Lidiane de Almeida Modesto","title":"Energy Research Analyst","org":"Empresa de Pesquisa Energética (EPE), Brazil","role":"Presentation"},{"name":"Filipe de Pádua","title":"","org":"Empresa de Pesquisa Energética (EPE), Brazil","role":"Presentation"}],"speakersStatus":"partial"},{"start":"10:00","end":"10:30","type":"break","title":"Coffee break"},{"id":"session-4","code":"Session 4","start":"10:30","end":"12:15","type":"session","title":"Planning under geopolitical uncertainty","partner":"Co-hosted with the World Energy Council","stage":"scenarios","summary":"Geopolitical volatility, fuel-price shocks and supply disruptions have moved energy security back to the centre of national planning. This session examines how countries stress-test scenarios against these risks, how the fossil-fuel transition and stranded-asset exposure are treated in national frameworks, and how alternative plans are conceived to respond to supply disruptions.","speakers":[{"name":"Norela Constantinescu","title":"Deputy Director, IRENA Innovation and Technology Centre","org":"IRENA","role":"Moderator"},{"name":"Reshma Francy","title":"Associate Director, Policy Pathfinding and World Energy Trilemma","org":"World Energy Council","role":"Scene-setting and panellist"},{"name":"Mungai Kihara","title":"Deputy Director, Renewable Energy","org":"Energy and Petroleum Regulatory Authority (EPRA), Kenya","role":"Panellist"},{"name":"Juan Lucero","title":"Coordinator","org":"National Energy Secretariat, Panama","role":"Panellist"},{"name":"Daniel Pérez Nombela","title":"Technical Advisor","org":"Ministry for the Ecological Transition and the Demographic Challenge (MITECO), Spain","role":"Panellist"}],"speakersStatus":"partial"},{"id":"ai-showcase","start":"12:15","end":"13:30","type":"meal","title":"Lunch session: state-of-the-art showcase of machine learning and artificial intelligence in energy planning","stage":"scenarios","summary":"A working-lunch showcase of applied AI uses prioritised by the LTES Network – demand and load forecasting, scenario development and sensitivity analysis, and data processing and quality assurance.","speakers":[{"name":"Nadeem Goussous","title":"","org":"IRENA","role":"Moderator"},{"name":"Matt Gray","title":"CEO and Co-Founder","org":"TransitionZero","role":"Use-case presentation"},{"name":"Dr. Charlie Heaps","title":"Senior Scientist","org":"Stockholm Environment Institute (SEI) US","role":"Use-case presentation"},{"name":"Prof. Mark Howells","title":"Professor of Systems Analysis for Sustainable Development, Loughborough University; Programme Director","org":"Climate Compatible Growth (CCG)","role":"Use-case presentation"},{"name":"Yunshu Li","title":"Energy Systems Analyst, Planning and Economic Studies Section","org":"International Atomic Energy Agency (IAEA)","role":"Use-case presentation"},{"name":"Dr. Alessandro Chiodi","title":"Partner and Operations Manager","org":"E4SMA","role":"Use-case presentation"},{"name":"Nabin Raj Gaihre","title":"Co-founder and Chief Revenue Officer","org":"VIDA","role":"Use-case presentation"},{"name":"Dietram Oppelt","title":"Vice-Chair","org":"UNFCCC Technology Executive Committee (TEC)","role":"Closing reflection"}],"speakersStatus":"partial"},{"id":"session-5","code":"Session 5","start":"13:30","end":"15:15","type":"session","title":"Climate risks and adaptation in national energy scenarios","stage":"scenarios","summary":"Climate variability and physical risks – heatwaves, floods, droughts and shifting hydrology – are stress-testing national energy systems in real time. This session examines how planning teams incorporate climate risks and adaptation into long-term scenarios: from El Niño-driven droughts in hydropower-dependent systems to cooling demand and flood exposure, and the data and methods needed to make plans resilient.","speakers":[{"name":"Alessia De Vita","title":"Advisor","org":"GET.transform","role":"Moderator"},{"name":"Ines Jacob","title":"Associate Programme Officer – Technology and Infrastructure","org":"IRENA","role":"Scene-setting speaker"},{"name":"Dr. Charlie Heaps","title":"Senior Scientist","org":"Stockholm Environment Institute (SEI) US","role":"Panellist"},{"name":"Dr. Seoungho Lee","title":"Associate Research Fellow","org":"Korea Energy Economics Institute (KEEI)","role":"Panellist"},{"name":"Brad Little","title":"Deputy Director, Electricity Policy","org":"Natural Resources Canada","role":"Panellist"},{"name":"Laura Cristina Marín Ortiz","title":"Subdirector of Electric Power","org":"Mining and Energy Planning Unit (UPME), Colombia","role":"Panellist"},{"name":"Dr. Maxime Gersch-Souvignet","title":"Head of Climate Analytics","org":"United Nations University Institute for Environment and Human Security (UNU-EHS)","role":"Panellist"},{"name":"Malaika Charles","title":"System Development Engineer","org":"St Lucia Electricity Services Limited, Saint Lucia","role":"Panellist"}],"speakersStatus":"partial"},{"start":"15:15","end":"15:45","type":"break","title":"Coffee break"},{"id":"session-6","code":"Session 6","start":"15:45","end":"17:30","type":"session","title":"Transformative methods, transformative scenarios?","stage":"scenarios","summary":"Scenario practice is evolving: deep uncertainty and robust decision-making, agent-based and participatory modelling, and open-source tools are moving from research into government planning, bringing new actors and interdisciplinary insights into the scenario-building process itself. This session examines how these methods can be navigated within the realities government planners face: resource constraints, institutional mandates and political viability.","speakers":[{"name":"Dr. Vivien Foster","title":"Principal Research Fellow, Centre for Environmental Policy","org":"Imperial College London","role":"Moderator"},{"name":"Jochen Bard","title":"Managing Director","org":"Fraunhofer CINES","role":"Panellist"},{"name":"Dr. Ema Gusheva","title":"Lecturer","org":"Utrecht University","role":"Panellist"},{"name":"Dr. Matías Paredes","title":"Energy Planning and Climate Change Analyst","org":"Ministry of Energy, Chile","role":"Panellist"},{"name":"Dr. Mohammad Amin Tahavori","title":"Researcher","org":"VITO/EnergyVille","role":"Panellist"}],"speakersStatus":"partial"},{"id":"day2-wrap","start":"17:30","end":"17:45","type":"plenary","title":"Day 2 wrap and bridge to Day 3","summary":"Joint reflections by IRENA and GET.transform.","speakers":[],"speakersStatus":"none"}]},{"id":"day-3","label":"Day 3","date":"2026-12-03","weekday":"Thursday","component":"gcep-dialogue","componentSwitch":{"afterItem":"lunch-d3","to":"implementation"},"theme":"From Planning to Investment and Implementation","parts":["Morning","Afternoon"],"items":[{"id":"ltes-strategic","start":"08:00","end":"09:00","type":"closed","title":"Closed-door session: LTES Network members and partners strategic meeting","access":"Closed-door: LTES Network members and partners only","speakers":[],"speakersStatus":"none","note":"Coffee and networking for all other participants, 08:00–09:00."},{"id":"opening-d3","start":"09:05","end":"09:25","type":"keynote","title":"Opening presentations","subtitle":"Findings from the GCEP regional dialogues on planning-to-investment bottlenecks","stage":"investment","summary":"Cross-regional findings from the Global Coalition for Energy Planning (GCEP) regional dialogues on the bottlenecks between planning and investment, and a perspective from GET.pro.","speakers":[{"name":"Juan José García Méndez","title":"GCEP Secretariat","org":"IRENA","role":"Presentation: findings from the GCEP regional dialogues on planning-to-investment bottlenecks"},{"name":"Daniel Werner","title":"Head of Programme","org":"GET.pro","role":"Presentation"}],"speakersStatus":"partial"},{"id":"session-7","code":"Session 7","start":"09:30","end":"11:00","type":"session","title":"From energy planning to investment decisions – the case of power utilities","partner":"Co-hosted with the World Bank","stage":"investment","summary":"Power-sector investment planning offers a concrete case in which scenario findings can guide specific investments, particularly where state-owned or vertically integrated utilities can commit to them. Building on initial findings from the GCEP Planning-to-Investment Dialogues, this session examines what planning requirements support the translation of long-term power-sector scenarios into investable plans, how these differ across investment arrangements – utility investment programmes, public procurement and private-sector investment – and how conditions such as utility creditworthiness, debt sustainability and financial risks can be considered during planning.","speakers":[{"name":"Dr. Asami Miketa","title":"Senior Energy Economist","org":"World Bank","role":"Moderator"},{"name":"José Campos","title":"Energy Transition Associate","org":"European Bank for Reconstruction and Development (EBRD)","role":"Expert perspective"},{"name":"Dr. Vivien Foster","title":"Principal Research Fellow, Centre for Environmental Policy","org":"Imperial College London","role":"Expert perspective"},{"name":"Mauricio Bernhardt Maciel","title":"Market Intelligence and Regulation Specialist, Energy Transition and Climate Division","org":"Brazilian Development Bank (BNDES)","role":"Expert perspective"}],"speakersStatus":"partial"},{"start":"11:00","end":"11:30","type":"break","title":"Coffee break"},{"id":"session-8","code":"Session 8","start":"11:30","end":"13:00","type":"session","title":"Planning the transition away from fossil fuels","partner":"Co-hosted with the Ministry for the Ecological Transition and the Demographic Challenge, Spain","stage":"investment","summary":"The transition away from fossil fuels (TAFF) agenda through the lens of investment-ready energy planning: how national planning systems can translate transition-away commitments into credible implementation pathways, and what practical support GCEP can provide to facilitate dialogue between planners, policymakers and financiers on the conditions needed to move from political commitment to investable action. It also reflects on the development and climate nexus.","speakers":[{"name":"Karen Grajeda","title":"","org":"IRENA","role":"Moderator"},{"name":"Luana Alves de Melo","title":"Diplomat, Energy Department","org":"Ministry of Foreign Affairs, Brazil","role":"Panellist"},{"name":"Alfonso Blanco","title":"Chief Operating Officer","org":"Fundación Ivy","role":"Panellist"},{"name":"Luis Martínez-Montoya","title":"Senior Advisor, Oil and Gas Transition","org":"International Institute for Sustainable Development (IISD)","role":"Panellist"},{"name":"Marta Muñoz","title":"Head of Service, Deputy Directorate-General for Energy Foresight and Statistics","org":"Ministry for the Ecological Transition and the Demographic Challenge (MITECO), Spain","role":"Panellist"}],"speakersStatus":"partial"},{"id":"lunch-d3","start":"13:00","end":"14:30","type":"meal","title":"Lunch break and working lunch session: Planning for universal access – turning national targets into a bankable last mile","summary":"Lunch from 13:00; the working lunch session runs from 13:00 to 14:00. Many countries now hold a national strategy or least-cost plan for universal access, yet turning it into a financed pipeline remains difficult, particularly in Sub-Saharan Africa. This working lunch brings government planners, regulators, data and tool providers, and financiers together in small groups around real country cases to examine where access plans stall on the way to investment and what would move them forward.","stage":"investment","speakers":[{"name":"Nolwazi Khumalo","title":"Programme Officer, Energy Planning Support and Capacity Building","org":"IRENA","role":"Moderator"},{"name":"Thierry Odou","title":"Associate Analyst, Off-Grid Power Systems","org":"IRENA","role":"Scene-setting speaker"},{"name":"Sina Makana","title":"Senior Economic Planner","org":"Ministry of Energy, Lesotho","role":"Country case"},{"name":"David Kibe Kariuki","title":"Head of Energy Planning","org":"Energy and Petroleum Regulatory Authority (EPRA), Kenya","role":"Country case"},{"name":"Tshering Yangki","title":"Principal Engineer","org":"Department of Energy, Bhutan","role":"Country case"},{"name":"Dimitris Mentis","title":"Global Lead, Energy Access Explorer (EAE)","org":"World Resources Institute (WRI)","role":"Partner intervention"},{"name":"Carlos Guerrero Lucendo","title":"Lead, International Climate and Energy Modelling, Water and Energy Transition Unit","org":"VITO","role":"Partner intervention"},{"name":"Dr. Joel Yongoua Nana","title":"Senior Manager","org":"Sustainable Energy Africa","role":"Partner intervention"},{"name":"Maisarah Abdul Kadir","title":"Associate Programme Officer, Energy and Socioeconomics Outlook (ESO)","org":"IRENA","role":"Closing and poll summary"}],"speakersStatus":"partial"},{"id":"session-9","code":"Session 9","start":"14:30","end":"15:45","type":"session","title":"From plans to delivery – how can planning support enabling energy markets?","stage":"implementation","summary":"What it takes to turn energy planning priorities into commercially viable projects, infrastructure and functioning markets. The session looks at what needs to happen from planning to action, from policy, regulation and procurement to market design and investment decisions, and where key barriers can emerge along the way, bringing together perspectives from different actors on how governments and planning institutions can create the conditions for investment and strengthen the link between long-term planning and delivery.","speakers":[{"name":"Toby Couture","title":"Director","org":"E3 Analytics","role":"Scene-setting speaker and moderator"},{"name":"Isabel Abreu","title":"Executive Director","org":"ALER","role":"Panellist"},{"name":"Sehlule Ndlovu","title":"International Project Officer","org":"SolarPower Europe","role":"Panellist"},{"name":"Dr. Sebastian Sterl","title":"Energy Planning and Modelling Specialist, Chief Economist Unit","org":"European Commission DG ENER","role":"Panellist"},{"name":"Dr. Benjamin Pflüger","title":"","org":"Fraunhofer IEG","role":"Panellist"}],"speakersStatus":"partial"},{"start":"15:45","end":"16:15","type":"break","title":"Coffee break"},{"id":"session-10","code":"Session 10","start":"16:15","end":"17:45","type":"session","title":"Country cases – when planning meets the market","stage":"implementation","summary":"Country case presentations from three angles. Planning enables the market (large scale): how long-term planning can inform large-scale project procurement and create a pipeline investors can respond to. The market moves faster than planning (distributed generation): what happens when markets, prosumers or new technologies such as battery storage move ahead of the assumptions in the plan, and how market information, investor behaviour, technology costs and emerging business models should feed back into planning. Planning enables infrastructure investment: how grid infrastructure enables functioning energy markets and private investment, and how planning can provide the long-term visibility, coordination and investment framework needed to develop it.","speakers":[{"name":"Daniel Russo","title":"Long-term Energy Planning Specialist","org":"IRENA","role":"Moderator"},{"name":"Ubaid Ullah Khan","title":"Specialist, Integrated Energy Planning","org":"Power Planning and Monitoring Company (PPMC), Pakistan","role":"Presenter"},{"name":"Lorena Melo Silva Perim","title":"Programme Director","org":"Ministry of Mines and Energy, Brazil","role":"Presenter"},{"name":"Dr. Bothwell Batidzirai","title":"Energy Market Reform Advisor","org":"African Union Commission","role":"Presenter"},{"name":"Saina Shirodkar","title":"Technical Assistant","org":"Goa Energy Development Agency, Government of Goa, India","role":"Presenter"},{"name":"Dr. Maximilian Parzen","title":"Co-founder and CEO","org":"Open Energy Transition (OET)","role":"Presenter"}],"speakersStatus":"partial"},{"id":"closing","start":"17:45","end":"18:00","type":"plenary","title":"Closing of Day 3","speakers":[{"name":"Christopher Gross","title":"Global Team Lead","org":"GET.transform","role":"Closing remarks"}],"speakersStatus":"partial"},{"id":"reception-d3","start":"18:00","end":"20:00","type":"social","title":"Reception","speakers":[],"speakersStatus":"none","note":"Foyer, GIZ Campus","location":"Foyer, GIZ Campus"}]},{"id":"day-4","label":"Day 4","date":"2026-12-04","weekday":"Friday","component":"partner-sessions","theme":"Energy Planning Deep Dives","items":[{"id":"breakfast-msp","start":"08:15","end":"09:00","type":"meal","title":"Coffee session: Connecting long-term energy scenarios with marine spatial planning","subtitle":"How closer coordination can lead to better results","stage":"scenarios","summary":"Marine spatial planning (MSP) determines how marine space is used and is a key enabler of accelerated, responsible offshore wind deployment – a growing part of many long-term energy scenarios. This session examines how energy planners and marine spatial planners can work together so that each process informs the other, using more granular MSP data to improve forecasts of timelines and infrastructure needs, with a focus on institutional coordination and data governance.","speakers":[{"name":"Anke Schoenlau","title":"Programme Officer, Offshore Wind and Climate Action","org":"IRENA","role":"Moderator"},{"name":"Dr. Laura Gușatu","title":"Postdoctoral Researcher","org":"University of Groningen","role":"Speaker"},{"name":"Rory O'Leary","title":"Principal Officer, Marine Strategic Policy Section","org":"Department of Climate, Energy and the Environment, Ireland","role":"Speaker"}],"speakersStatus":"partial"},{"id":"deep-dive-1","code":"Deep Dive 1","start":"09:00","end":"10:00","type":"session","title":"Greening data centres – principles for sound energy planning under uncertainty","stage":"scenarios","summary":"AI and data centres are driving rapid growth in electricity demand. Poorly planned, this new demand can strain networks and raise emissions; well-designed procurement and siting can instead accelerate additional renewables, flexibility and grid investment. Building on IRENA's work on green data centres, this session explores how principles for credible renewable electricity supply can be linked with system and infrastructure planning to address anticipated data centre demand despite prevailing uncertainty.","speakers":[{"name":"Dr. James Walker","title":"Head of Unit – Systemic Innovation","org":"IRENA","role":"Moderator"},{"name":"Mohammad Rizki Kresnawan","title":"","org":"ASEAN Centre for Energy (ACE), Indonesia","role":"Speaker"},{"name":"Dr. Atsede Gualu Endegnanew","title":"Senior Energy Modeller","org":"Eastern Africa Power Pool (EAPP)","role":"Speaker"},{"name":"Mohd Najib Mohd Shah","title":"","org":"Energy Commission (Suruhanjaya Tenaga), Malaysia","role":"Speaker"},{"name":"Rohit Sen","title":"Head of Sustainable Energy","org":"ICLEI – Local Governments for Sustainability","role":"Speaker"},{"name":"Nicola Magnani","title":"Project Leader, Materials and Strategic Supply Chains for the Energy Transition","org":"European Commission Joint Research Centre (JRC)","role":"Speaker"}],"speakersStatus":"partial"},{"id":"deep-dive-2","code":"Deep Dive 2","start":"10:00","end":"11:00","type":"session","title":"Robust power system planning – linking grid infrastructure and flexibility","partner":"Co-hosted with the Green Grids Initiative","stage":"investment","summary":"As solar and wind shares grow and electrification reshapes demand, power systems need more grid capacity and more flexibility, and the two are closely linked. This session shares experiences in connecting national energy scenarios with grid and flexibility planning: where grid expansion is needed, where flexibility offers a cost-effective complement, and how to avoid unnecessary investment while maintaining reliability.","speakers":[{"name":"Francisco Gafaro","title":"Team Lead – Power Sector Transformation","org":"IRENA","role":"Moderator"},{"name":"Dr. Matías Paredes","title":"Energy Planning and Climate Change Analyst","org":"Ministry of Energy, Chile","role":"Panellist"},{"name":"Helena Lindquist","title":"Lighthouse Project Manager","org":"International Smart Grid Action Network (ISGAN)","role":"Panellist"},{"name":"Jimmy Cesar Gonzales Arispe","title":"Head of Electrical Studies Division","org":"Comité Nacional de Despacho de Carga (CNDC), Bolivia","role":"Panellist"},{"name":"Prof. Jairo Quirós-Tortós","title":"Professor of Practice – Sustainable Transitions, Loughborough University; Deputy Director, Climate Compatible Growth (CCG)","org":"Green Grids Initiative (GGI)","role":"Panellist"}],"speakersStatus":"partial"},{"start":"11:00","end":"11:30","type":"break","title":"Coffee break"},{"id":"deep-dive-3","code":"Deep Dive 3","start":"11:30","end":"13:00","type":"session","title":"Regional energy planning – aligning national priorities and regional interconnection","partner":"Co-hosted with the African Union Commission","stage":"policy","summary":"Regional institutions and planning entities from different world regions share how national plans inform regional transmission development and vice versa, the institutional mechanisms that support coordination, and the challenges that remain.","speakers":[{"name":"Thomas Schmitz","title":"","org":"GIZ","role":"Moderator"},{"name":"Shehu Ibrahim Khaleel","title":"Senior Energy Advisor","org":"African Union Commission","role":"Keynote"},{"name":"Dr. Sebastian Sterl","title":"Energy Planning and Modelling Specialist, Chief Economist Unit","org":"European Commission DG ENER","role":"Keynote"},{"name":"Alfonso Blanco","title":"Chief Operating Officer","org":"Fundación Ivy","role":"Panellist"},{"name":"Yudiandra Yuwono","title":"Lead Modeller","org":"ASEAN Centre for Energy (ACE)","role":"Panellist"},{"name":"Sydney Zimba","title":"Operations Engineer","org":"Southern African Power Pool (SAPP)","role":"Panellist"},{"name":"Abdurashid Mirzaev","title":"Chief Dispatcher","org":"Coordinating Dispatch Center (CDC) \"Energia\", Uzbekistan","role":"Panellist"}],"speakersStatus":"partial"},{"id":"closing-d4","start":"13:00","end":"13:15","type":"plenary","title":"Closing remarks","speakersStatus":"partial","speakers":[{"name":"Dr. Ricardo Gorini","title":"Head of Unit, ESO","org":"IRENA","role":"Closing remarks"}]},{"start":"13:15","end":"14:00","type":"meal","title":"Lunch"}]}]},"publications":{"items":[{"year":2025,"title":"Participatory processes for strategic energy planning","subtitle":"A toolkit for national energy planners","image":"images/publications/participatory-toolkit-2025.jpg","url":"https://www.irena.org/Publications/2025/Sep/Participatory-processes-for-strategic-energy-planning-A-toolkit-for-national-energy-planners"},{"year":2023,"title":"Scenarios for the energy transition","subtitle":"Experience and good practices in Africa","image":"images/publications/africa-2023.jpg","url":"https://www.irena.org/Publications/2023/Jan/Scenarios-for-the-energy-transition-Experience-and-good-practices-in-Africa"},{"year":2023,"title":"LTES and low-emission development strategies","subtitle":"Stocktaking and alignment","image":"images/publications/ltes-leds-2023.jpg","url":"https://www.irena.org/Publications/2023/Jan/LTES-and-low-emission-development-strategies-Stocktaking-and-alignment"},{"year":2022,"title":"Scenarios for the energy transition","subtitle":"Experience and good practices in Latin America and the Caribbean","image":"images/publications/lac-2022.jpg","url":"https://www.irena.org/Publications/2022/Jul/Scenarios-for-the-Energy-Transition-LAC"},{"year":2021,"title":"Benchmarking scenario comparisons","subtitle":"Key indicators for the clean energy transition","image":"images/publications/benchmarking-2021.jpg","url":"https://www.irena.org/Publications/2021/Sep/Benchmarking-Scenario-Comparisons"},{"year":2020,"title":"Scenarios for the energy transition","subtitle":"Global experience and best practices","image":"images/publications/global-2020.jpg","url":"https://www.irena.org/Publications/2020/Sep/Scenarios-for-the-Energy-Transition-Global-experience-and-best-practices"}],"getTransform":{"items":[{"label":"Publication · Nov 2026","title":"From Policy to Bankable Projects","text":"Impact case study on capacity building and technical assistance for competitive renewable energy tenders under GET.transform’s Policy Catalyst window.","image":"images/publications/gt-polcat.jpg","links":[{"label":"Read the publication","url":"https://www.get-transform.eu/from-policy-to-bankable-projects/"}]},{"label":"News · Nov 2026","title":"Policy Catalyst: African and Caribbean countries on a joint path to competitive renewable energy tenders","text":"Officials from 14 countries met in Cape Town for the first in-person training of the Capacity Building Academy for Renewable Energy Tenders.","image":"images/publications/gt-srmi.jpg","links":[{"label":"Read the story","url":"https://www.get-transform.eu/policy-catalyst-african-and-caribbean-countries-on-joint-path-to-competitive-renewable-energy-tenders/"}]},{"label":"Country story · Namibia","title":"Long-term energy planning in Namibia","text":"Training for the country’s first Energy Outlook, to 2070, and on open-source modelling with PyPSA for the National Integrated Resource Plan.","image":"images/publications/gt-namibia.jpg","links":[{"label":"Namibia’s first Energy Outlook: planning for 2070","url":"https://www.get-transform.eu/namibias-first-energy-outlook-planning-for-2070/"},{"label":"Open-source tool informs long-term energy planning","url":"https://www.get-transform.eu/open-source-tool-informs-long-term-energy-planning-in-namibia/"}]},{"label":"Country story · Panama","title":"A new National Energy Plan for Panama","text":"Panama’s National Energy Secretariat is updating the National Energy Plan 2026–2040, with long-term planning training and a multi-stakeholder scenario workshop.","image":"images/publications/gt-panama.jpg","links":[{"label":"Planning a sustainable energy future for Panama","url":"https://www.get-transform.eu/planning-a-sustainable-energy-future-for-panama/"},{"label":"Building a resilient electricity sector in Panama","url":"https://www.get-transform.eu/building-a-resilient-electricity-sector-in-panama/"}]},{"label":"Country story · Pakistan","title":"Integrated energy planning in Pakistan","text":"GIZ Pakistan and E4SMA are building PAK-IEM 2.0, a TIMES-based integrated energy model with a least-cost baseline and a net-zero-by-2050 scenario.","image":"images/publications/gt-pakistan.jpg","links":[{"label":"Shaping smarter energy decisions through integrated planning","url":"https://www.get-transform.eu/shaping-smarter-energy-decisions-in-pakistan-through-integrated-planning/"}]}]}},"speakers":{"people":[{"name":"Abdurashid Mirzaev","title":"Chief Dispatcher","org":"Coordinating Dispatch Center (CDC) \"Energia\", Uzbekistan","id":"abdurashid-mirzaev","photo":"","appearances":[{"item":"deep-dive-3","role":"Panellist","component":"partner-sessions"}]},{"name":"Dr. Alessandro Chiodi","title":"Partner and Operations Manager","org":"E4SMA","bio":"Alessandro Chiodi is Partner and Operations Manager at E4SMA, an Italian consultancy providing energy and climate planning and policy services, and has worked there since 2010 on energy and environmental decision-support models, scenario analysis and policy review. An energy systems modeller working extensively with the TIMES modelling framework, Dr. Chiodi has contributed to European research projects including PARIS REINFORCE, on integrated assessment modelling in support of the Paris Agreement, and earlier developed climate and energy scenarios for Ireland to 2050 with the Irish TIMES model.","id":"alessandro-chiodi","photo":"alessandro-chiodi.webp","appearances":[{"item":"ai-showcase","role":"Use-case presentation","component":"ltes-forum"}]},{"name":"Alessia De Vita","title":"Advisor","org":"GET.transform","bio":"Alessia De Vita is Advisor for Long-Term Energy Planning and Renewable Energy Grid Integration at GET.transform, and contributed as an expert speaker to IRENA's 5th International Forum on Long-Term Energy Scenarios.","id":"alessia-de-vita","photo":"alessia-de-vita.webp","appearances":[{"item":"session-2","role":"Panellist","component":"ltes-forum"},{"item":"session-5","role":"Moderator","component":"ltes-forum"}]},{"name":"Alfonso Blanco","title":"Chief Operating Officer","org":"Fundación Ivy","bio":"Alfonso Blanco is Chief Operating Officer of Fundación Ivy and an energy and environment expert with more than 20 years in leadership positions, heading transformational processes across the energy sector in Uruguay and Latin America and the Caribbean. Until March 2023 he was Executive Director of the Latin American Energy Organization (OLADE), elected in 2016 and re-elected in 2019, where he promoted regional energy integration, strengthened sectoral information systems and supported the energy transition across the region. He is a Senior International Consultant for the World Bank, the Inter-American Development Bank (IDB) and energy sector companies, and has advised CAF, the United Nations and GIZ. In Uruguay, he was one of the leaders of the transformation of the energy sector, leading the design of energy efficiency and biomass policies. His expertise covers energy regulation, public policy, energy diplomacy, climate change, project development and evaluation, and financing models for energy transitions. He holds a degree in mechanical industrial engineering from the University of the Republic (UdelaR), Uruguay, an MBA from Universidad ORT Uruguay, graduate studies in economics and an Executive Certificate in Public Policy from Harvard Kennedy School.","id":"alfonso-blanco","photo":"alfonso-blanco.webp","appearances":[{"item":"session-8","role":"Panellist","component":"gcep-dialogue"},{"item":"deep-dive-3","role":"Panellist","component":"partner-sessions"}]},{"name":"Anke Schoenlau","title":"Programme Officer, Offshore Wind and Climate Action","org":"IRENA","bio":"Anke Schoenlau is a Programme Officer for Offshore Wind and Climate Action at IRENA. In this capacity, she also supports the Secretariat of the Global Offshore Wind Alliance (GOWA).","id":"anke-schoenlau","photo":"anke-schoenlau.webp","appearances":[{"item":"breakfast-msp","role":"Moderator","component":"partner-sessions"}]},{"name":"Dr. Asami Miketa","title":"Senior Energy Economist","org":"World Bank","bio":"Asami Miketa is a Senior Energy Economist in the Policy and Regulation unit of the World Bank's Global Energy Practice. Before joining the World Bank, Dr Miketa led energy planning work at IRENA's Innovation and Technology Centre in Bonn for around 13 years, and earlier worked as an energy planner at the International Atomic Energy Agency (IAEA).","id":"asami-miketa","photo":"asami-miketa.webp","appearances":[{"item":"session-7","role":"Moderator","component":"gcep-dialogue"}]},{"name":"Dr. Atsede Gualu Endegnanew","title":"Senior Energy Modeller","org":"Eastern Africa Power Pool (EAPP)","bio":"Dr. Atsede Gualu Endegnanew is a power systems engineer with over 15 years of experience in power systems and energy modelling, power system planning, renewable energy integration and mini-grid development. She has served as a Senior Energy Modeler at the Eastern Africa Power Pool, contributing to regional generation and transmission planning. She has extensive experience providing technical assistance in power system studies, high-voltage direct current (HVDC) interconnections, institutional capacity building and technical training. Previously, she led the design and development of nine pilot mini-grids in Ethiopia and conducted research on renewable energy integration, power system stability, wind energy and HVDC technologies. She has authored over 30 scientific publications.","id":"atsede-gualu-endegnanew","photo":"atsede-gualu-endegnanew.webp","appearances":[{"item":"deep-dive-1","role":"Speaker","component":"partner-sessions"}]},{"name":"Dr. Benjamin Pflüger","title":"","org":"Fraunhofer IEG","id":"benjamin-pfluger","photo":"benjamin-pfluger.webp","appearances":[{"item":"session-9","role":"Panellist","component":"implementation"}]},{"name":"Dr. Bothwell Batidzirai","title":"Energy Market Reform Advisor","org":"African Union Commission","bio":"Dr. Bothwell Batidzirai is an Energy Market Reform Advisor at the African Union Commission’s Infrastructure and Energy Department, seconded by GIZ under the ENGAGE programme. He supports the operationalisation of the African Single Electricity Market (AfSEM), working with African institutions on market reforms, regulatory frameworks and regional power trade. He was also part of the expert team that developed the African Continental Power Sector Masterplan (CMP). An electrical engineer with a PhD in energy systems analysis from Utrecht University, he has extensive experience in energy planning, policy and capacity building across Africa. His work focuses on transforming African energy systems towards greater sustainability to catalyse inclusive green growth.","id":"bothwell-batidzirai","photo":"bothwell-batidzirai.webp","appearances":[{"item":"session-10","role":"Presenter","component":"implementation"}]},{"name":"Brad Little","title":"Deputy Director, Electricity Policy","org":"Natural Resources Canada","bio":"Brad Little is Deputy Director, Electricity Policy at Natural Resources Canada, where he works with federal and provincial partners, electric utilities and other stakeholders to strengthen Canada's regional and national electricity grids and support the transition to a low-carbon future. His experience includes electricity policy roles at Finance Canada and Natural Resources Canada, and serving as the Canadian federal government's non-voting representative on the Reliability and Security Technical Committee of the North American Electric Reliability Corporation (NERC). He brings a policy and economics perspective to discussions of long-term energy scenarios, with particular interest in transmission infrastructure, interregional cooperation and electricity system reliability. He holds a Master of Public Administration from Carleton University.","id":"brad-little","photo":"brad-little.webp","appearances":[{"item":"session-2","role":"Moderator and scene-setting speaker","component":"ltes-forum"},{"item":"session-5","role":"Panellist","component":"ltes-forum"}]},{"name":"Carlos Guerrero Lucendo","title":"Lead, International Climate and Energy Modelling, Water and Energy Transition Unit","org":"VITO","bio":"Carlos Guerrero Lucendo is a senior researcher and project manager at VITO. His work focuses on long-term energy system modelling, climate reporting, energy access and the water–energy–food nexus. He works with governments and local stakeholders across Africa to co-develop energy and emissions scenarios, assess policy options and strengthen local modelling capacity.","id":"carlos-guerrero-lucendo","photo":"carlos-guerrero-lucendo.webp","appearances":[{"item":"lunch-d3","role":"Partner intervention","component":"gcep-dialogue"}]},{"name":"Dr. Charlie Heaps","title":"Senior Scientist","org":"Stockholm Environment Institute (SEI) US","bio":"Charlie Heaps is a Senior Scientist at SEI US and the developer of LEAP, the Low Emissions Analysis Platform, a software tool for integrated energy planning and climate change mitigation assessment in development by Dr. Heaps since 1990. More than 1,000 people use LEAP each month, and its online community had grown to over 60,000 members in more than 200 countries by 2023. LEAP has been used by more than 60 national governments to help develop their official climate plans, and is widely used by NGOs and by more than 300 universities and research centres. Dr. Heaps was SEI US Center Director from 2006 to 2014 and Energy Modeling Program Director from 2015 to 2024, and works around the world conducting workshops, undertaking studies and providing training and assistance to LEAP users. Academic qualifications are a degree in energy studies from Swansea University and a PhD in environmental technology from Imperial College London.","photo":"charlie-heaps.webp","id":"charlie-heaps","appearances":[{"item":"ai-showcase","role":"Use-case presentation","component":"ltes-forum"},{"item":"session-5","role":"Panellist","component":"ltes-forum"}]},{"name":"Christopher Gross","title":"Global Team Lead","org":"GET.transform","id":"christopher-gross","photo":"christopher-gross.webp","appearances":[{"item":"closing","role":"Closing remarks","component":"implementation"}]},{"name":"Dr. Ir. Dadan Kusdiana","title":"Secretary General","org":"National Energy Council (DEN), Indonesia","bio":"Dadan Kusdiana has been Secretary General of Indonesia's National Energy Council (DEN) since 2025. He joined the Ministry of Energy and Mineral Resources (MEMR) in 1992 and has spent his career there, most recently as Secretary General (2023–2025), Director General of New and Renewable Energy and Energy Conservation (2020–2023) and Head of the Research and Development Agency (2019–2020). From 2017 to 2019 he was Senior Advisor to the Minister on Economics and Natural Resources. Earlier roles include Head of the Bureau of Communication, Public Information Services and Cooperation, and Director of Bioenergy, where he led the nationwide roll-out of palm-oil biodiesel. He holds a doctorate and a master's degree in energy science from Kyoto University, specialising in biofuel process technology, and a bachelor's degree in agricultural engineering from Bogor Agricultural University (IPB).","id":"dadan-kusdiana","photo":"dadan-kusdiana.webp","appearances":[{"item":"session-1","role":"Panellist","component":"ltes-forum"}]},{"name":"Daniel Pérez Nombela","title":"Technical Advisor","org":"Ministry for the Ecological Transition and the Demographic Challenge (MITECO), Spain","bio":"Daniel Pérez Nombela is Technical Adviser at the Deputy Directorate-General for Energy Foresight and Statistics of Spain's Ministry for the Ecological Transition and the Demographic Challenge (MITECO), where he contributes to the modelling of Spain's energy system and to the development of major strategic policy documents. He previously worked on the design and administration of funding programmes for energy storage projects under Spain's Recovery, Transformation and Resilience Plan. He is an industrial engineer by training.","id":"daniel-perez-nombela","photo":"daniel-perez-nombela.webp","appearances":[{"item":"session-4","role":"Panellist","component":"ltes-forum"}]},{"name":"Daniel Russo","title":"Long-term Energy Planning Specialist","org":"IRENA","bio":"Daniel Russo is a long-term energy planning specialist at the International Renewable Energy Agency (IRENA), based at its Innovation and Technology Centre in Bonn, and has more than 12 years of experience in the energy and climate sectors. Since joining IRENA in 2016, he has supported energy planning in Africa, Asia and Latin America. His work there includes leading national and regional capacity-building programmes with government ministries and power pools, developing long-term power-sector models and renewable energy roadmaps, and modelling variable renewable energy to inform policy. He has also been a key contributor to IRENA's work on smart electrification and its Long-term Energy Scenarios initiative. Before IRENA, he worked in energy and economic modelling consultancy, innovation policy research and finance.","id":"daniel-russo","photo":"daniel-russo.webp","appearances":[{"item":"session-10","role":"Moderator","component":"implementation"}]},{"name":"Daniel Werner","title":"Head of Programme","org":"GET.pro","id":"daniel-werner","photo":"daniel-werner.webp","appearances":[{"item":"opening-d3","role":"Presentation","component":"gcep-dialogue"}]},{"name":"David Kibe Kariuki","title":"Head of Energy Planning","org":"Energy and Petroleum Regulatory Authority (EPRA), Kenya","bio":"David Kibe Kariuki leads the energy planning function in the Economic Regulation Directorate of Kenya's Energy and Petroleum Regulatory Authority (EPRA), where he has been a lead economist, including in its predecessor institutions, since 2010. His responsibilities include coordinating indicative energy plans and cost-of-service studies; petroleum data collection, analysis and dissemination; pricing and rate setting for energy services; performance contracting; monitoring and evaluation of energy sector utilities; and developing regulations relevant to energy planning. He has more than 33 years of experience in planning, policy analysis, research, and monitoring and evaluation, with earlier roles at the Ministry of Planning and National Development, the Institute of Policy Analysis and Research (IPAR) and projects supported by the World Bank and UNDP. He holds a bachelor's degree in economics from the University of Nairobi and a master's degree in economic policy management from Makerere University, Uganda, as well as postgraduate qualifications in monitoring and evaluation, economic modelling, public sector utilities regulation, leadership and strategic planning.","id":"david-kibe-kariuki","photo":"david-kibe-kariuki.webp","appearances":[{"item":"lunch-d3","role":"Country case","component":"gcep-dialogue"}]},{"name":"Dr. Derck Koolen","title":"Energy Policy Economist","org":"European Commission DG ENER","bio":"Derck Koolen is an Energy Policy Economist at the European Commission's Directorate-General for Energy (DG ENER), leading energy system and market modelling work and providing economic analysis for the design of EU energy policy. Dr. Koolen is also an Assistant Professor at Utrecht University School of Economics and a research affiliate of the Energy Institute at Haas, University of California, Berkeley, and of the Energy Markets Group at London Business School. Earlier work as an energy economist in London, Hamburg and Rotterdam covered energy systems, markets and finance. Dr. Koolen's research on energy economics has appeared in journals including The Energy Journal, Energy Policy and Applied Energy. Academic qualifications include a PhD in economics from Erasmus University Rotterdam and an MSc in engineering from the University of Leuven.","id":"derck-koolen","photo":"derck-koolen.webp","appearances":[{"item":"session-3","role":"Moderator","component":"ltes-forum"}]},{"name":"Dietram Oppelt","title":"Vice-Chair","org":"UNFCCC Technology Executive Committee (TEC)","bio":"Dietram Oppelt is Vice-Chair of the UNFCCC Technology Executive Committee (TEC), where he works to advance global climate technology solutions. He has more than 30 years of experience managing and coordinating projects on climate mitigation, climate finance and energy efficiency, supporting the development and transfer of low- and zero-emission technologies and contributing to sectoral mitigation strategies in more than ten countries, across energy, buildings, industry, transport, waste and agriculture. Years of professional experience in Japan and China give him a deep understanding of regional climate strategies and innovation needs. He holds an MSc from the London School of Economics, a bachelor's degree from the University of St. Gallen, Switzerland, and postgraduate qualifications from the University of Tokyo.","id":"dietram-oppelt","photo":"dietram-oppelt.webp","appearances":[{"item":"ai-showcase","role":"Closing reflection","component":"ltes-forum"}]},{"name":"Dimitris Mentis","title":"Global Lead, Energy Access Explorer (EAE)","org":"World Resources Institute (WRI)","bio":"Dimitris Mentis leads Energy Access Explorer (EAE) at the World Resources Institute (WRI), the first digital public good in the energy domain. With 17 years of experience in geospatial technology and energy systems, he focuses on open-source, dynamic geospatial platforms that support data-informed, integrated and inclusive energy planning. These help governments, businesses, financiers and development practitioners identify high-priority areas for energy interventions that drive socio-economic development, while strengthening data management and governance and reducing software engineering and data transaction costs. He holds a PhD in Energy and Environmental Systems and an MSc in Sustainable Energy Engineering from KTH Royal Institute of Technology, Sweden, and BSc and MSc degrees in Mechanical Engineering and Energy Engineering from the National Technical University of Athens (NTUA), Greece. His work has received several awards, including International Energy Project of the Year (Energy Awards, 2026), the Future of Government Award (2025), the Energy Globe Award for Outstanding Contribution (2024) and the GEO for SDGs Award (2023).","id":"dimitris-mentis","photo":"dimitris-mentis.webp","appearances":[{"item":"lunch-d3","role":"Partner intervention","component":"gcep-dialogue"}]},{"name":"Edouard Clement","title":"Executive Director","org":"Energy Modelling Hub (EMH)","bio":"Edouard Clement is the Executive Director of the Energy Modelling Hub, a pan-Canadian independent centre that supports evidence-based energy policymaking by advancing open data, modelling tools, and collaboration across government, academia, and industry. Trained in Mechanical Engineering and Aeronautics at Polytechnique Montréal, Edouard has built his career at the intersection of technology, sustainability, and decision-support systems. Before leading the Energy Modelling Hub, he worked as a Research Associate at ÉTS and at General Electric's hydro division, then directed Polytechnique Montréal's CIRAIG, overseeing major Life Cycle Assessment projects for public and private clients. As an entrepreneur, he co-founded Quantis Canada and later Novisto, two ventures that helped shape how organisations integrate environmental and ESG data into strategy and reporting. With 25 years of experience bridging science, policy, and business, Edouard brings deep expertise in life cycle assessment, GHG accounting, and sustainable design to his leadership of Canada's energy modelling ecosystem.","photo":"edouard-clement.webp","id":"edouard-clement","appearances":[{"item":"session-2","role":"Scene-setting speaker","component":"ltes-forum"}]},{"name":"Dr. Ema Gusheva","title":"Lecturer","org":"Utrecht University","bio":"Ema Gusheva is a Lecturer at the Copernicus Institute of Sustainable Development at Utrecht University, where she teaches on master's and bachelor's programmes in energy science. Her doctoral research at Delft University of Technology examined the science-policy interface in the energy transition, asking when and how decision-makers actually use computational models and what that means for climate policy. Before her PhD, she worked with the United Nations Development Programme (UNDP) in North Macedonia, supporting national modellers and policymakers on energy planning and climate change policy.","id":"ema-gusheva","photo":"ema-gusheva.webp","appearances":[{"item":"session-6","role":"Panellist","component":"ltes-forum"}]},{"name":"Filipe de Pádua","title":"","org":"Empresa de Pesquisa Energética (EPE), Brazil","bio":"Filipe de Pádua Fernandes Silva is an energy researcher at Brazil's Energy Research Office (Empresa de Pesquisa Energética, EPE) and General Executive Coordinator of the Ten-Year Energy Expansion Plan (PDE 2035), and has also authored EPE studies on international oil and oil-product prices.","id":"filipe-de-padua","photo":"filipe-de-padua.webp","appearances":[{"item":"impact-brazil","role":"Presentation","component":"ltes-forum"}]},{"name":"Dr. Florian Knobloch","title":"Senior Policy Advisor, Scenarios and Economic Aspects of the Energy Transition","org":"Federal Ministry for Economic Affairs and Energy (BMWE), Germany","bio":"Florian Knobloch is Senior Policy Advisor for Scenarios and Economic Aspects of the Energy Transition at Germany's Federal Ministry for Economic Affairs and Energy (BMWE), where he is responsible for the ministry's long-term energy scenario studies. He was previously Deputy Head of the Division for Climate and Energy Cooperation. An economist and environmental scientist by training, he holds a PhD from Radboud University Nijmegen, the Netherlands, on modelling technology choice behaviour in energy transitions, an MPhil in Environmental Policy from the University of Cambridge, and an MSc and BSc in Economics from Humboldt University of Berlin.","id":"florian-knobloch","photo":"florian-knobloch.webp","appearances":[{"item":"session-2","role":"Panellist","component":"ltes-forum"}]},{"name":"Francisco Gafaro","title":"Team Lead – Power Sector Transformation","org":"IRENA","bio":"Francisco Gafaro is Team Lead on Power Sector Transformation at IRENA's Innovation and Technology Centre (IITC) in Bonn, Germany. He holds a master's degree in electrical power engineering from RWTH Aachen University. With more than 20 years of experience in power system planning, operations and renewable energy integration, he has led power system transformation efforts across Latin America, Europe and the Pacific Islands, contributing to national and international energy strategies. He has overseen updates to grid planning, connection, operational and market practices to support the integration of more renewable energy.","id":"francisco-gafaro","photo":"francisco-gafaro.webp","appearances":[{"item":"deep-dive-2","role":"Moderator","component":"partner-sessions"}]},{"name":"Girvan Pigott","title":"Director of Energy","org":"Ministry of ICTs, Utilities and Energy, Antigua and Barbuda","bio":"Girvan Pigott has been Director of Energy of Antigua and Barbuda since August 2026, leading the Energy Department of the Ministry of Information Communication Technologies (ICTs), Utilities and Energy. He oversees the implementation of national energy policies and programmes, including work to improve energy efficiency, expand renewable energy and build a more resilient and sustainable energy sector. He brings more than 20 years of experience in the energy and utilities industry. Before his appointment, he was a Project Engineer at the Antigua Public Utilities Authority (APUA), where he was involved in planning and delivering several key infrastructure projects.","id":"girvan-pigott","photo":"","appearances":[{"item":"session-1","role":"Panellist","component":"ltes-forum"}]},{"name":"Hanaa Chabini","title":"Head of Observation and Forecasting Department, Directorate of Strategy, Forecasting, Observation and Cooperation","org":"Ministry of Energy Transition and Sustainable Development, Morocco","bio":"Hanaa Chabini is Head of the Observation and Forecasting Department at Morocco's Ministry of Energy, Mining and Sustainable Development. Her expertise covers energy data and statistics, indicators, data analysis, sectoral surveys on final energy consumption, energy modelling and prospective studies, as well as national energy balances and greenhouse gas inventories in line with international standards. She has contributed to national and international activities on energy, modelling and climate policy, and has delivered training and peer-learning sessions for experts from several countries at the request of organisations including the International Atomic Energy Agency (IAEA), international universities and the CBIT-GSP Middle East and North Africa programme. Her work focuses on strengthening energy information systems to support evidence-based policymaking and long-term energy planning.","id":"hanaa-chabini","photo":"hanaa-chabini.webp","appearances":[{"item":"session-3","role":"Panellist","component":"ltes-forum"}]},{"name":"Hanne Jersild","title":"Chief Advisor","org":"Denmark","id":"hanne-jersild","photo":"","appearances":[{"item":"opening","role":"Welcome remarks","component":"ltes-forum"}]},{"name":"Helena Lindquist","title":"Lighthouse Project Manager","org":"International Smart Grid Action Network (ISGAN)","id":"helena-lindquist","photo":"helena-lindquist.webp","appearances":[{"item":"deep-dive-2","role":"Panellist","component":"partner-sessions"}]},{"name":"Ines Jacob","title":"Associate Programme Officer – Technology and Infrastructure","org":"IRENA","id":"ines-jacob","photo":"ines-jacob.webp","appearances":[{"item":"session-5","role":"Scene-setting speaker","component":"ltes-forum"}]},{"name":"Isabel Abreu","title":"Executive Director","org":"ALER","bio":"Isabel Cancela de Abreu is Executive Director of the Lusophone Renewable Energy Association (ALER), having led the project that created it. An environmental engineer from Instituto Superior Técnico, she also holds a Diploma of Advanced Studies in Sustainable Energy Systems from the MIT Portugal programme. After a period at the creative start-up YDreams, she built her career in renewable energy associations, at APREN, the Portuguese Renewable Energy Association, and at its European counterpart, EREC. She has also volunteered in Niassa, Mozambique, completed an internship at Grameen Bank in Bangladesh and helped organise Sun Aid's Global Solar Academy in Évora.","id":"isabel-abreu","photo":"isabel-abreu.webp","appearances":[{"item":"session-9","role":"Panellist","component":"implementation"}]},{"name":"Ivo Nacucchio","title":"Data and Modelling Expert","org":"Latin American and Caribbean Energy Organization (OLACDE)","bio":"Ivo Nacucchio is a data and modelling expert at the Latin American and Caribbean Energy Organization (OLACDE), working on regional energy data integration, electricity and gas interconnection studies in the Southern Cone, and open-source tools for energy planning.","id":"ivo-nacucchio","photo":"ivo-nacucchio.webp","appearances":[{"item":"session-3","role":"Panellist","component":"ltes-forum"}]},{"name":"Prof. Jairo Quirós-Tortós","title":"Professor of Practice – Sustainable Transitions, Loughborough University; Deputy Director, Climate Compatible Growth (CCG)","org":"Green Grids Initiative (GGI)","id":"jairo-quiros-tortos","photo":"jairo-quiros-tortos.webp","appearances":[{"item":"deep-dive-2","role":"Panellist","component":"partner-sessions"}]},{"name":"Dr. James Walker","title":"Head of Unit – Systemic Innovation","org":"IRENA","bio":"Dr. James Walker is Head of Unit – Systemic Innovation at the International Renewable Energy Agency (IRENA), which supports 173 member countries in driving the widespread adoption of renewable energy. Based at IRENA’s Innovation and Technology Centre in Bonn, Germany, he manages a programme of work that identifies novel and innovative solutions and approaches across the whole renewable energy value chain, and highlights the measures needed to accelerate their uptake. He and his team focus in particular on renewable energy applications in the “hard-to-abate” end-use sectors of industry and heavy-duty transport, managing IRENA’s analysis of pathways for electrifying industrial processes and of the role of renewable hydrogen and derivative commodities such as ammonia and methanol as future fuels.","id":"james-walker","photo":"james-walker.webp","appearances":[{"item":"deep-dive-1","role":"Moderator","component":"partner-sessions"}]},{"name":"Jean-François Gagné","title":"Head of the CEM Secretariat","org":"Clean Energy Ministerial (CEM)","bio":"Jean-François Gagné is Head of the Secretariat of the Clean Energy Ministerial (CEM) and has more than 20 years of experience across transportation, energy and environmental protection. Before joining the CEM Secretariat, he was Executive Director of International Affairs at Natural Resources Canada, where he developed and implemented Canada's global energy engagement strategy, managed bilateral and multilateral collaboration mechanisms, and represented Canada as lead energy negotiator. He previously spent five years leading the International Energy Agency's collaborative work programme on sustainable energy technologies, policies and strategies. He began his career in the aerospace industry before moving to the Canadian public sector, where he led transportation, energy and environmental technology programmes, advised the Canadian Armed Forces, the Canadian Coast Guard and Natural Resources Canada, and managed programmes supporting the Government of Canada's sustainable development objectives. He holds a master's degree in mechanical and aerospace engineering.","id":"jean-francois-gagne","photo":"jean-francois-gagne.webp","appearances":[{"item":"opening","role":"Welcome remarks","component":"ltes-forum"}]},{"name":"Jimmy Cesar Gonzales Arispe","title":"Head of Electrical Studies Division","org":"Comité Nacional de Despacho de Carga (CNDC), Bolivia","id":"jimmy-cesar-gonzales-arispe","photo":"jimmy-cesar-gonzales-arispe.webp","appearances":[{"item":"deep-dive-2","role":"Panellist","component":"partner-sessions"}]},{"name":"Jochen Bard","title":"Managing Director","org":"Fraunhofer CINES","bio":"Jochen Bard is Managing Director of Fraunhofer CINES. A physicist trained at the University of Karlsruhe, Dr Bard led the Energy Process Technology division at Fraunhofer IEE in Kassel and is a co-founder of the Hydrogen Science Coalition.","id":"jochen-bard","photo":"jochen-bard.webp","appearances":[{"item":"session-6","role":"Panellist","component":"ltes-forum"}]},{"name":"Dr. Joel Yongoua Nana","title":"Senior Manager","org":"Sustainable Energy Africa","bio":"Joel Yongoua Nana is a Senior Manager at Sustainable Energy Africa and a Fellow at the Energy for Growth Hub. Dr. Nana's work across Africa covers the grid integration of distributed energy resources, urban energy profiling, city-wide energy system modelling and electric mobility, with capacity building for policymakers built into each project. Academic qualifications include a PhD from the Energy Systems Research Group at the University of Cape Town, an MSc in Applied Physics and a BEng in Electrical Engineering.","id":"joel-yongoua-nana","photo":"joel-yongoua-nana.webp","appearances":[{"item":"session-3","role":"Panellist","component":"ltes-forum"},{"item":"lunch-d3","role":"Partner intervention","component":"gcep-dialogue"}]},{"name":"José Campos","title":"Energy Transition Associate","org":"European Bank for Reconstruction and Development (EBRD)","bio":"José Imer Campos is an Energy Transition Associate at the European Bank for Reconstruction and Development (EBRD), the London-based multilateral development bank, working on the decarbonisation of energy systems through investment, policy engagement and technical assistance. His experience spans climate policy, sustainable finance, impact investing and banking, including previous roles with the Green Climate Fund, the Mitigation Action Facility, WWF and the venture capital fund Stella Maris Partners. He holds a Master of Public Policy from the Hertie School, Germany, and a BA in Financial Management from Tecnológico de Monterrey, Mexico.","id":"jose-campos","photo":"jose-campos.webp","appearances":[{"item":"session-7","role":"Expert perspective","component":"gcep-dialogue"}]},{"name":"Juan José García Méndez","title":"GCEP Secretariat","org":"IRENA","bio":"Juan José García is a Programme Officer at the International Renewable Energy Agency (IRENA), leading the Global Long-Term Energy Scenarios (LTES) Network. With over 17 years of experience in renewable energy, energy policy, and long-term energy planning, he specializes in energy system modelling, policy development, and international collaboration for clean energy transitions.","photo":"juan-garcia.webp","id":"juan-jose-garcia-mendez","appearances":[{"item":"opening-d3","role":"Presentation: findings from the GCEP regional dialogues on planning-to-investment bottlenecks","component":"gcep-dialogue"}]},{"name":"Juan Lucero","title":"Coordinator","org":"National Energy Secretariat, Panama","bio":"Juan Lucero coordinates the development of Panama's National Energy Plan at the National Energy Secretariat. An electromechanical engineer from the Technological University of Panama, with a master's degree in project management and a specialisation in energy and climate change, he has more than 15 years of professional experience. He has worked in electricity distribution and the building industry in the private sector, and in the energy sector in government. Since 2020 he has worked with non-governmental organisations on implementation of the Montreal Protocol, climate change mitigation policy and greenhouse gas scenarios.","id":"juan-lucero","photo":"juan-lucero.webp","appearances":[{"item":"session-4","role":"Panellist","component":"ltes-forum"}]},{"name":"Kamil Maqsood","title":"Team Lead – Policy","org":"Power Planning and Monitoring Company (PPMC), Pakistan","id":"kamil-maqsood","photo":"kamil-maqsood.webp","appearances":[{"item":"session-2","role":"Panellist","component":"ltes-forum"}]},{"name":"Karen Grajeda","title":"","org":"IRENA","id":"karen-grajeda","photo":"","appearances":[{"item":"session-8","role":"Moderator","component":"gcep-dialogue"}]},{"name":"Dr. Larissa Nogueira","title":"Team Lead, Energy Planning","org":"IRENA","bio":"Larissa Nogueira leads a team of energy system analysts in IRENA's Energy Planning and Power Sector Transformation team. She oversees IRENA's key power sector modelling – capacity expansion, flexibility and off-grid analysis – and ensures quality and consistency across the power sector tools used in IRENA's work, from regional outlooks to capacity building. She has more than a decade of experience in energy system analysis and techno-economic assessment of clean energy technologies, and has supported and led energy planning and climate policy initiatives across regions with governments, the private sector, intergovernmental organisations and non-governmental organisations.","photo":"larissa-pinheiro.webp","id":"larissa-nogueira","appearances":[{"item":"session-1","role":"Scene-setting speaker","component":"ltes-forum"}]},{"name":"Laura Cristina Marín Ortiz","title":"Subdirector of Electric Power","org":"Mining and Energy Planning Unit (UPME), Colombia","bio":"Laura Cristina Marín Ortiz is Subdirector of Electric Power at Colombia's Mining and Energy Planning Unit (UPME). With more than 17 years in the energy sector, earlier roles include operations coordination analyst at XM, Colombia's power system operator, and project leader at PHC Consultores Energéticos from 2016. An electrical engineer, Laura holds a master's degree in power systems from Germany and is a certified Project Management Professional (PMP).","id":"laura-cristina-marin-ortiz","photo":"laura-cristina-marin-ortiz.webp","appearances":[{"item":"session-5","role":"Panellist","component":"ltes-forum"}]},{"name":"Dr. Laura Gușatu","title":"Postdoctoral Researcher","org":"University of Groningen","bio":"Laura Gușatu is a postdoctoral researcher in the Planning Department of the Faculty of Spatial Sciences at the University of Groningen, the Netherlands, working on the ECOAMARE project (Ecosystem-based Adaptive Management for Renewable energy in a sustainable North Sea), financed by the Dutch Research Council (NWO). Through her current research, she engages with stakeholders and policymakers to formulate spatially explicit scenarios and adaptive pathways for possible futures of the Dutch offshore energy sector. In her previous work she developed tools and frameworks to support strategic, long-term energy planning and decision-making, including frameworks for quantifying offshore conflicts and synergies, studies coupling spatial scenarios with basin-scale energy models, and spatio-temporal assessments of the cumulative environmental impacts of large-scale offshore wind deployment.","id":"laura-gusatu","photo":"laura-gusatu.webp","appearances":[{"item":"breakfast-msp","role":"Speaker","component":"partner-sessions"}]},{"name":"Prof. Leboli Zak Thamae","title":"Coordinator, Energy Research Centre","org":"National University of Lesotho (NUL)","bio":"Prof. Leboli Zak Thamae is Coordinator of the Energy Research Centre (ERC) at the National University of Lesotho (NUL), where he leads interdisciplinary research on sustainable energy systems. His work focuses on the intersection of energy technology, policy, regulation and sustainable development, with expertise in computational modelling for energy planning, renewable energy integration, rural electrification, green electric mobility and infrastructure governance. He has extensive experience in energy policy analysis, strategic planning, advisory services, training and applied research. Through the NUL ERC, he collaborates with government, industry, development partners and international institutions to support evidence-based policymaking, capacity building and sustainable energy transitions.","id":"leboli-zak-thamae","photo":"leboli-zak-thamae.webp","appearances":[{"item":"session-2","role":"Panellist","component":"ltes-forum"}]},{"name":"Lidiane de Almeida Modesto","title":"Energy Research Analyst","org":"Empresa de Pesquisa Energética (EPE), Brazil","bio":"Lidiane de Almeida Modesto is an Energy Research Analyst at Brazil's Energy Research Office (Empresa de Pesquisa Energética, EPE), contributing to major energy planning studies, including the Ten-Year Energy Expansion Plan (PDE) and the National Energy Plan 2055 (PNE 2055), with a focus on long-term energy scenarios and resource assessment. She has developed macroeconomic analyses supporting the Quarterly Electricity Load Review, in collaboration with Brazil's National Electric System Operator (ONS), and medium- and long-term scenarios for the federal government's energy planning. An economist, she holds a master's degree in economics from the State University of Rio de Janeiro (UERJ).","id":"lidiane-de-almeida-modesto","photo":"lidiane-de-almeida-modesto.webp","appearances":[{"item":"impact-brazil","role":"Presentation","component":"ltes-forum"}]},{"name":"Lorena Melo Silva Perim","title":"Programme Director","org":"Ministry of Mines and Energy, Brazil","bio":"Lorena Melo Silva Perim has been a civil servant at Brazil's Ministry of Mines and Energy (MME) since 2012. In July 2025 she was appointed Program Director to the National Secretary for Energy Transition and Planning and designated alternate to the National Secretary, and from February to June 2026 she served as Acting National Secretary. From 2023 to 2025 she was Coordinator and then General Coordinator in the General Coordination Office for Transmission Planning, where she coordinated transmission expansion studies with the Energy Research Office (EPE), the National Electric System Operator (ONS) and the Brazilian Electricity Regulatory Agency (ANEEL), and oversaw studies on international electricity interconnections. Earlier, she served as an Advisor in the Department of Energy Planning and worked on electricity auctions, sectoral funds and regulatory charges in the Special Advisory Office for Economic Affairs. She holds Bachelor's and Master's degrees in electrical engineering from the University of Brasília (UnB), and postgraduate qualifications in public policy and government management from PUC-Rio and in energy transition from Fundação Getulio Vargas (FGV).","id":"lorena-melo-silva-perim","photo":"lorena-melo-silva-perim.webp","appearances":[{"item":"session-10","role":"Presenter","component":"implementation"}]},{"name":"Luana Alves de Melo","title":"Diplomat, Energy Department","org":"Ministry of Foreign Affairs, Brazil","bio":"Luana Melo is a Brazilian career diplomat at the Ministry of Foreign Affairs, currently serving in its Energy Department. Her work focuses on international energy affairs, including the energy transition, sustainable development and international cooperation. Throughout her career she has worked on infrastructure, regional integration and international cooperation, and she has served at Brazilian diplomatic missions in Bolivia, France and Angola, where she coordinated different teams and areas of work. Her experience combines diplomacy, public policy and international engagement.","id":"luana-alves-de-melo","photo":"luana-alves-de-melo.webp","appearances":[{"item":"session-8","role":"Panellist","component":"gcep-dialogue"}]},{"name":"Luciano Caratori","title":"Global Energy Cluster Lead","org":"Climate Champions Team","bio":"Luciano Caratori is Global Energy Cluster Lead in the Climate Champions Team. He joined from the Centre of Studies on Global Climate Change at Instituto and Fundación Torcuato Di Tella (ITDT/FTDT) in Argentina, where his work on energy policy for the energy transition, just transitions and climate action planning centred on energy data and scenario planning. He previously served as Undersecretary of Energy Planning and National Director of Energy Information in Argentina's federal government, and as advisor to the vice-chair of the Mining, Energy and Fuels Committee of the National Senate. He represented Argentina in the G20 Energy Transitions Working Group and the Secretariat of Energy in the National Cabinet for Climate Change. As an independent consultant, he has valued energy assets, assessed the transition risks facing energy companies and advised local and national governments on energy planning.","id":"luciano-caratori","photo":"luciano-caratori.webp","appearances":[{"item":"session-1","role":"Panellist","component":"ltes-forum"}]},{"name":"Luis Martínez-Montoya","title":"Senior Advisor, Oil and Gas Transition","org":"International Institute for Sustainable Development (IISD)","bio":"Luis Martínez-Montoya is Senior Advisor for Oil and Gas Transition at the International Institute for Sustainable Development (IISD), where his work focuses on energy security, fossil fuel subsidy reform and the energy transition in Mexico. He has more than 20 years of experience across the public, private and multilateral sectors. In the private sector, he led regulatory strategies for the development of renewable energy and green hydrogen infrastructure in Mexico and served as corporate diplomat for two deepwater exploration contracts in the Gulf of Mexico. He has worked with the World Bank and the Latin American Energy Organization (OLADE) on energy sector governance and regional methane mitigation strategies, and held management positions at Mexico's Ministry of Energy and its National Agency for Industrial Safety and Environmental Protection of the Hydrocarbons Sector (ASEA). He holds a Master of Arts in International Relations and International Economics, with a concentration in Energy Resources and Environment, from the Johns Hopkins University School of Advanced International Studies (SAIS), and is a PhD candidate in International Relations, Business and Diplomacy at the Universidad Autónoma de Nuevo León.","id":"luis-martinez-montoya","photo":"luis-martinez-montoya.webp","appearances":[{"item":"session-8","role":"Panellist","component":"gcep-dialogue"}]},{"name":"Prof. Maarten Hajer","title":"Distinguished Professor of Urban Futures and Futuring; Director, Urban Futures Studio","org":"Utrecht University","bio":"Maarten A. Hajer is Distinguished Professor of Urban Futures and Futuring at Utrecht University and Director of its Urban Futures Studio. He was previously Professor of Public Policy at the University of Amsterdam (1998–2015) and Director-General of PBL Netherlands Environmental Assessment Agency (2008–2015). From 2010 to 2025 he was a member of UNEP's International Resource Panel, where he co-chaired the working group on cities, and from 2016 to 2024 he was Scientific Director of Utrecht University's strategic theme \"Pathways to Sustainability\". He was Chief Curator of the International Architecture Biennale Rotterdam (IABR) in 2016 and is a research fellow of the Centre for Sustainability Transitions at Stellenbosch University. His books include The Politics of Environmental Discourse (Oxford University Press, 1995) and, most recently, Captured Futures – Rethinking the Drama of Environmental Politics (with Jeroen Oomen, Oxford University Press, 2025). He holds master's degrees in political science and in urban and regional planning from the University of Amsterdam and a DPhil in Politics from the University of Oxford.","id":"maarten-hajer","photo":"maarten-hajer.webp","appearances":[{"item":"keynote-d1","role":"Keynote speaker","component":"ltes-forum"}]},{"name":"Maisarah Abdul Kadir","title":"Associate Programme Officer, Energy and Socioeconomics Outlook (ESO)","org":"IRENA","bio":"Maisarah Abdul Kadir is an Associate Programme Officer at IRENA's Innovation and Technology Centre in Bonn. Her work focuses on developing global, regional and national energy scenario pathways for demand-side and end-use sectors. She has worked extensively on developing energy models for Africa, Southeast Asia and Central America.","id":"maisarah-abdul-kadir","photo":"maisarah-abdul-kadir.webp","appearances":[{"item":"lunch-d3","role":"Closing and poll summary","component":"gcep-dialogue"}]},{"name":"Malaika Charles","title":"System Development Engineer","org":"St Lucia Electricity Services Limited, Saint Lucia","id":"malaika-charles","photo":"","appearances":[{"item":"session-5","role":"Panellist","component":"ltes-forum"}]},{"name":"Marie Rousselot","title":"Head of Market Intelligence","org":"Enerdata, France","bio":"Marie Rousselot is Head of Market Intelligence at Enerdata, with extensive experience in energy data, indicators and long-term scenario development. She has led and contributed to international projects on energy demand modelling, energy efficiency indicators and prospective energy and climate scenarios, working with governments, public agencies and international institutions. Her expertise lies particularly in connecting historical data and monitoring frameworks with scenario modelling and policy analysis.","id":"marie-rousselot","photo":"marie-rousselot.webp","appearances":[{"item":"session-3","role":"Panellist","component":"ltes-forum"}]},{"name":"Prof. Mark Howells","title":"Professor of Systems Analysis for Sustainable Development, Loughborough University; Programme Director","org":"Climate Compatible Growth (CCG)","bio":"Professor Mark Howells is a leading authority in sustainable energy systems analysis, holding joint appointments as a Professor at Loughborough University and a Principal Research Fellow at Imperial College London. His work focuses on developing data-driven tools and policy frameworks to guide the global transition to sustainable energy, influencing policy at the highest levels. He has advised and collaborated with prominent institutions including NASA, Google, the World Bank Group, the United Nations, and the European Commission. Professor Howells is renowned for co-developing the \"Data-to-Deal\" (D2D) framework, a revolutionary approach that empowers countries to build local capacity and unlock investment for national climate transitions. The framework's pioneering implementation in Costa Rica enabled the creation of a data-driven National Decarbonization Plan. The strategy, costing approximately $200,000 in direct expenses per country, has successfully mobilized an estimated $10 billion USD in international climate finance in three examples. Underpinning this success are open-source modelling toolkits and starter data he helped oversee, which have been translated into global public goods and downloaded hundreds of thousands of times. His leadership in the field is substantial. Professor Howells directs the £95 million www.ClimateCompatibleGrowth.com (CCG) research programme for the UK government and is the joint director of the £200 million STEER centre. He formally ran the EC's official Energy thinktank Insight-e, and also serves as Editor-in-Chief of the Energy Strategy Reviews journal. With an H-index of 62 and over 167 peer-reviewed publications, his research continues to shape global energy strategy. He previously served as an Energy Planner at the International Atomic Energy Agency (IAEA) and as Head of the Division of Energy Systems Analysis at KTH Royal Institute of Technology in Sweden. He holds a PhD in Energy Studies from the University of Cape Town.","photo":"mark-howells.webp","id":"mark-howells","appearances":[{"item":"ai-showcase","role":"Use-case presentation","component":"ltes-forum"}]},{"name":"Marta Muñoz","title":"Head of Service, Deputy Directorate-General for Energy Foresight and Statistics","org":"Ministry for the Ecological Transition and the Demographic Challenge (MITECO), Spain","bio":"Marta Muñico Muñoz is Head of Service at the Deputy Directorate-General for Energy Foresight and Statistics of Spain's Ministry for the Ecological Transition and the Demographic Challenge (MITECO). Her work focuses on energy system modelling, long-term energy planning and the design of strategic energy and climate policies. She is involved in preparing major national policy instruments, including Spain's National Energy and Climate Plan (NECP) and its Long-Term Decarbonisation Strategy 2050. She is an industrial engineer by training.","id":"marta-munoz","photo":"marta-munoz.webp","appearances":[{"item":"session-8","role":"Panellist","component":"gcep-dialogue"}]},{"name":"Dr. Matías Paredes","title":"Energy Planning and Climate Change Analyst","org":"Ministry of Energy, Chile","photo":"matias-paredes.webp","bio":"Matías Paredes-Vergara is an Analyst in the Planning and Climate Change Unit of Chile's Ministry of Energy, where he works on improving and developing the country's long-term energy planning process, with a focus on power system planning. His research addresses applied decision-making in long-term energy planning, including integrating decision-making under deep uncertainty (DMDU) into institutional frameworks and building tailored optimisation models for power system planning, such as the optimal routing of transmission lines using mathematical modelling and GIS data. Before joining the ministry, he worked on green hydrogen development, solar photovoltaic projects and water resources projects in Chile, in both the private and public sectors. He holds a PhD in Systems Engineering and a bachelor's degree in Civil Engineering from the University of Chile.","id":"matias-paredes","appearances":[{"item":"session-2","role":"Scene-setting speaker and panellist","component":"ltes-forum"},{"item":"session-6","role":"Panellist","component":"ltes-forum"},{"item":"deep-dive-2","role":"Panellist","component":"partner-sessions"}]},{"name":"Matt Gray","title":"CEO and Co-Founder","org":"TransitionZero","bio":"Matt Gray is CEO and Co-Founder of TransitionZero and an energy market analyst with more than a decade of sell-side and consulting experience. Before founding TransitionZero, Matt was head of European carbon and power research at the American investment bank Jefferies, and has also been a consultant to the International Energy Agency and a managing director of the power and utilities team at Carbon Tracker. Matt holds a BAppSci in Environmental Management from the University of Otago and an MSc in Environmental Governance from the University of Manchester, the latter completed with a Rotary Foundation Scholarship.","id":"matt-gray","photo":"matt-gray.webp","appearances":[{"item":"ai-showcase","role":"Use-case presentation","component":"ltes-forum"}]},{"name":"Mauricio Bernhardt Maciel","title":"Market Intelligence and Regulation Specialist, Energy Transition and Climate Division","org":"Brazilian Development Bank (BNDES)","bio":"Mauricio Bernhardt Maciel is a Market Intelligence and Regulation Specialist in the Energy Transition and Climate Division of the Brazilian Development Bank (BNDES). Since joining the bank in 2009, he has worked on credit assessment for the power sector, with a focus on renewable generation projects. He holds a degree in chemical engineering from the Federal University of Rio de Janeiro (UFRJ) and a Master of Business Administration from the COPPEAD Graduate School of Business (COPPEAD/UFRJ).","id":"mauricio-bernhardt-maciel","photo":"mauricio-bernhardt-maciel.webp","appearances":[{"item":"session-7","role":"Expert perspective","component":"gcep-dialogue"}]},{"name":"Dr. Maxime Gersch-Souvignet","title":"Head of Climate Analytics","org":"United Nations University Institute for Environment and Human Security (UNU-EHS)","bio":"Maxime Gersch-Souvignet is Head of Climate Analytics at the United Nations University Institute for Environment and Human Security (UNU-EHS), where he leads the development of quantitative climate risk analytics, disaster risk modelling and adaptation research. He has more than 15 years of international experience in climate risk assessment, flood and hydrological modelling, adaptation planning and climate finance, working across Africa, Asia, Latin America and Europe. His work combines advanced risk modelling, geospatial analytics and decision-support tools such as CLIMADA to help governments, development banks and international organisations strengthen resilience to climate change. He holds a PhD in hydrology and climatology and has authored numerous scientific publications on climate risk, adaptation and disaster resilience.","id":"maxime-gersch-souvignet","photo":"maxime-gersch-souvignet.webp","appearances":[{"item":"session-5","role":"Panellist","component":"ltes-forum"}]},{"name":"Dr. Maximilian Parzen","title":"Co-founder and CEO","org":"Open Energy Transition (OET)","bio":"Dr. Maximilian Parzen is co-founder and CEO of Open Energy Transition (OET), a nonprofit advancing open-source energy planning worldwide. He works with grid operators, regulators, governments and researchers to turn open tools and data into better decisions on electricity systems, grid investment and the energy transition. A former contributor and maintainer of PyPSA, he combines technical expertise with a focus on institutional adoption and international collaboration. He holds a PhD in energy system modelling and energy storage from the University of Edinburgh. At OET, he champions transparent, accessible and reproducible planning to support affordable, reliable and clean energy for all.","id":"maximilian-parzen","photo":"maximilian-parzen.webp","appearances":[{"item":"session-10","role":"Presenter","component":"implementation"}]},{"name":"Dr. Mohammad Amin Tahavori","title":"Researcher","org":"VITO/EnergyVille","bio":"Mohammad Amin Tahavori is an energy systems researcher at VITO/EnergyVille in Belgium, specialising in energy system optimisation, long-term scenario development and quantitative analysis to support energy transition strategies and policymaking. He has contributed to national energy and climate planning in developing countries, including the development of nationally determined contributions (NDCs) and long-term low-emission development strategies (LT-LEDS), working closely with policymakers, international organisations and energy sector stakeholders. His recent work focuses on European energy transition pathways, renewable energy integration, energy infrastructure, industrial decarbonisation and cross-sectoral interactions. Combining modelling with policy analysis and stakeholder engagement, his work aims to bridge the gap between complex energy system models and actionable strategies for a sustainable energy transition. He holds a master's degree in energy engineering.","photo":"mohammad-amin-tahavori.webp","id":"mohammad-amin-tahavori","appearances":[{"item":"session-6","role":"Panellist","component":"ltes-forum"}]},{"name":"Mohammad Rizki Kresnawan","title":"","org":"ASEAN Centre for Energy (ACE), Indonesia","id":"mohammad-rizki-kresnawan","photo":"mohammad-rizki-kresnawan.webp","appearances":[{"item":"deep-dive-1","role":"Speaker","component":"partner-sessions"}]},{"name":"Mohd Najib Mohd Shah","title":"","org":"Energy Commission (Suruhanjaya Tenaga), Malaysia","id":"mohd-najib-mohd-shah","photo":"mohd-najib-mohd-shah.webp","appearances":[{"item":"deep-dive-1","role":"Speaker","component":"partner-sessions"}]},{"name":"Mungai Kihara","title":"Deputy Director, Renewable Energy","org":"Energy and Petroleum Regulatory Authority (EPRA), Kenya","bio":"Mungai Kihara is Deputy Director, Renewable Energy, at Kenya's Energy and Petroleum Regulatory Authority (EPRA), in its Directorate of Electricity and Renewable Energy. Recent work includes the regulatory framework for solar water heating in Kenya.","id":"mungai-kihara","photo":"mungai-kihara.webp","appearances":[{"item":"session-4","role":"Panellist","component":"ltes-forum"}]},{"name":"Nabin Raj Gaihre","title":"Co-founder and Chief Revenue Officer","org":"VIDA","bio":"Nabin Raj Gaihre is co-founder and Chief Revenue Officer of VIDA, a geospatial data platform for planning and monitoring infrastructure investments. VIDA combines satellite imagery, remote sensing and machine learning to produce decision-ready data on settlements, demand, infrastructure, accessibility, climate risk and socio-economic conditions. Governments, utilities, development finance institutions and private developers use it in more than 60 countries, mainly in Africa and developing Asia, to plan electricity infrastructure. Much of this work is for client governments of donors. Nabin leads VIDA's commercial, delivery and customer teams. He is a power engineer by training, holds a degree from the Technical University of Munich and has more than a decade of experience building digital solutions for the energy sector. He is originally from Nepal and lives in Munich.","id":"nabin-raj-gaihre","photo":"nabin-raj-gaihre.webp","appearances":[{"item":"ai-showcase","role":"Use-case presentation","component":"ltes-forum"}]},{"name":"Nadeem Goussous","title":"","org":"IRENA","bio":"Nadeem Goussous is an Associate Programme Officer at the International Renewable Energy Agency (IRENA), where he works in the team leading the Global Network on Long-term Energy Scenarios (LTES), engaging with countries and experts worldwide from diverse sectors to advance energy planning practices. He currently leads the workstream on participatory processes for energy scenario development, bringing together policymakers, researchers, industry representatives, and civil society stakeholders to enhance participatory energy planning. He has also led and contributed to several publications on energy and climate planning. His work focuses on developing best practices for robust and inclusive national energy transition pathways. Previously, Nadeem worked as an R&D Engineer in renewable energy resource assessment. He holds a Master's degree in Global Energy Transition and Governance and a Bachelor's degree in Electrical and Electronic Engineering.","photo":"nadeem-goussous.webp","id":"nadeem-goussous","appearances":[{"item":"ai-showcase","role":"Moderator","component":"ltes-forum"}]},{"name":"Nicola Magnani","title":"Project Leader, Materials and Strategic Supply Chains for the Energy Transition","org":"European Commission Joint Research Centre (JRC)","bio":"Nicola Magnani leads the \"Materials and strategic supply chains for the energy transition\" project at the European Commission's Joint Research Centre (JRC), and has been a Commission official since 2016. Before that, he spent fifteen years in academia as a quantum physicist with a strong focus on materials science, nanotechnology and statistical mechanics. Alongside his team's work on critical raw materials, he is strongly interested in better understanding the science–policy interface and improving how scientific results are communicated to policymakers.","id":"nicola-magnani","photo":"nicola-magnani.webp","appearances":[{"item":"deep-dive-1","role":"Speaker","component":"partner-sessions"}]},{"name":"Nolwazi Khumalo","title":"Programme Officer, Energy Planning Support and Capacity Building","org":"IRENA","bio":"Nolwazi Khumalo is an energy professional specialising in energy planning support and capacity building across Africa. She has more than a decade of experience in energy systems planning and modelling, working with governments and international organisations to develop investable long-term plans and sustainable energy strategies by translating complex technical data into actionable policies. She is also dedicated to building institutional capacity, fostering stakeholder engagement and promoting good practice to advance energy planning and renewable energy integration.","id":"nolwazi-khumalo","photo":"nolwazi-khumalo.webp","appearances":[{"item":"lunch-d3","role":"Moderator","component":"gcep-dialogue"}]},{"name":"Norela Constantinescu","title":"Deputy Director, IRENA Innovation and Technology Centre","org":"IRENA","bio":"Norela Constantinescu is Deputy Director at the IRENA Innovation and Technology Centre. Until May 2024 she was Head of Innovation Section with ENTSO-E, the European Network for Transmission System Operators for electricity, for which she worked for 10 years, starting in 2014. In the period June 2022 – March 2024 she was Chair of the European Technology and Innovation Platform for Smart Networks for Energy Transition. Previously she worked with the European Commission DG Energy on low-carbon technologies, wind, and smart cities and communities. She is an energy engineer with postgraduate studies in business administration and applied computer science.","photo":"norela-constantinescu.webp","id":"norela-constantinescu","appearances":[{"item":"opening","role":"Welcome remarks","component":"ltes-forum"},{"item":"session-4","role":"Moderator","component":"ltes-forum"}]},{"name":"Reshma Francy","title":"Associate Director, Policy Pathfinding and World Energy Trilemma","org":"World Energy Council","bio":"Reshma Francy is Associate Director, Policy Pathfinding and World Energy Trilemma, at the World Energy Council, with more than a decade of experience in clean energy and climate change. She leads the Council's World Energy Trilemma programme, including the Trilemma report launched at the World Energy Congress in April 2024, and is developing the Trilemma Framework – energy security, energy equity and environmental sustainability – into a policy pathfinding tool that combines quantitative frameworks with current energy narratives. She previously managed the Council's World Energy Scenarios programme, designing scenario workshops and using its policy simulator for national and regional pathways. Before joining the Council, she was a policymaker in the United Arab Emirates, where she led the creation of the country's first national energy strategy and was a member of its Paris Agreement negotiating team, contributing to its first nationally determined contribution. She is pursuing a PhD at the Technical University of Munich School of Politics on the role of actors in enabling energy transitions in the Gulf States.","photo":"reshma-francy.webp","id":"reshma-francy","appearances":[{"item":"session-4","role":"Scene-setting and panellist","component":"ltes-forum"}]},{"name":"Dr. Ricardo Gorini","title":"Head of Unit, ESO","org":"IRENA","id":"ricardo-gorini","photo":"ricardo-gorini.webp","appearances":[{"item":"closing-d4","role":"Closing remarks","component":"partner-sessions"}]},{"name":"Rohit Sen","title":"Head of Sustainable Energy","org":"ICLEI – Local Governments for Sustainability","bio":"Rohit Sen is Head of Sustainable Energy at ICLEI World Secretariat, Bonn, with 16+ years in renewable energy, clean-energy finance and project development across four continents. He leads global work on 100% renewable cities and regions, and focuses on how grids, buildings, heat and new loads such as data centres can be planned locally and financed at scale.","id":"rohit-sen","photo":"rohit-sen.webp","appearances":[{"item":"deep-dive-1","role":"Speaker","component":"partner-sessions"}]},{"name":"Rory O'Leary","title":"Principal Officer, Marine Strategic Policy Section","org":"Department of Climate, Energy and the Environment, Ireland","bio":"Rory O’Leary is Head of Marine Strategic Policy in the EU, International and Marine Affairs Division of Ireland’s Department of Climate, Energy and the Environment. The role covers developing and maintaining a strategic marine policy and legislative framework aligned with national and international objectives; leading cross-government and external engagement, nationally and internationally, on strategic marine policy issues; developing and implementing marine legislation; and overseeing outreach, engagement and citizen activation measures.","id":"rory-o-leary","photo":"rory-o-leary.webp","appearances":[{"item":"breakfast-msp","role":"Speaker","component":"partner-sessions"}]},{"name":"Saina Shirodkar","title":"Technical Assistant","org":"Goa Energy Development Agency, Government of Goa, India","bio":"Saina Shirodkar is a Technical Assistant at the Goa Energy Development Agency (GEDA), Government of Goa, India. She is involved in implementing Goa's Clean Energy Roadmap 2050, with a focus on renewable energy, e-mobility, climate action and multisectoral energy planning, including initiatives such as Net Positive Panchayat, Mission Net Zero Campus, Green Cooking and solar applications from agrivoltaics and floating solar to community solar with battery storage. She has supported the Chief Minister of Goa in advancing renewable energy interventions across the state and contributed to the Goa Renewable Energy Policy and Bioenergy Policy. She works with government departments, international development partners such as GIZ and technical institutions on policy drafting and implementation, stakeholder engagement and capacity building, and is engaged in the PM E-DRIVE programme for EV charging infrastructure, the Model Solar Village programme and the Green Hydrogen Valley Innovation Cluster for Goa. She holds a Master's degree in electrical engineering, specialising in power and energy systems engineering.","id":"saina-shirodkar","photo":"saina-shirodkar.webp","appearances":[{"item":"session-10","role":"Presenter","component":"implementation"}]},{"name":"Sarah Rieseberg","title":"Policy Officer","org":"Federal Ministry for the Environment, Climate Action, Nature Conservation and Nuclear Safety (BMUKN), Germany","id":"sarah-rieseberg","photo":"","appearances":[{"item":"session-1","role":"Panellist","component":"ltes-forum"}]},{"name":"Dr. Sebastian Sterl","title":"Energy Planning and Modelling Specialist, Chief Economist Unit","org":"European Commission DG ENER","bio":"Sebastian Sterl is Energy Planning and Modelling Specialist in the Chief Economist Unit of the European Commission's Directorate-General for Energy (DG ENER). He oversees and coordinates model-based analyses of clean energy transition planning, renewables integration, grid expansion scenarios and energy system resilience, supporting the EU's efforts to increase its independence from fossil fuels and meet its energy and climate targets. He is also a part-time professor of energy meteorology at the Vrije Universiteit Brussel (VUB).","photo":"sebastian-sterl.webp","id":"sebastian-sterl","appearances":[{"item":"session-9","role":"Panellist","component":"implementation"},{"item":"deep-dive-3","role":"Keynote","component":"partner-sessions"}]},{"name":"Sehlule Ndlovu","title":"International Project Officer","org":"SolarPower Europe","id":"sehlule-ndlovu","photo":"sehlule-ndlovu.webp","appearances":[{"item":"session-9","role":"Panellist","component":"implementation"}]},{"name":"Dr. Seoungho Lee","title":"Associate Research Fellow","org":"Korea Energy Economics Institute (KEEI)","bio":"Seoungho Lee is an Associate Research Fellow at the Korea Energy Economics Institute (KEEI), where he conducts research within the Department of Long-term Energy Modelling. His work focuses on developing and analysing Korea's Long-term Energy Outlook, supporting evidence-based policymaking through quantitative modelling and scenario analysis. Holding a Ph.D. in Economics, Lee's research interests include energy demand forecasting, macroeconomic linkages in energy transitions, and the integration of statistical insights into national energy planning.","photo":"seoungho-lee.webp","id":"seoungho-lee","appearances":[{"item":"session-5","role":"Panellist","component":"ltes-forum"}]},{"name":"Shehu Ibrahim Khaleel","title":"Senior Energy Advisor","org":"African Union Commission","bio":"Shehu Ibrahim Khaleel is a senior energy policy, electricity-market integration and technical advisory specialist with over 25 years of international experience advancing Africa’s energy transformation. As Senior Energy Advisor, he supports the African Union Commission’s Department of Infrastructure and Energy in developing and implementing continental, regional and national frameworks for electricity market integration, regulatory harmonisation, energy transition and cross-border electricity trade, contributing to the African Single Electricity Market (AfSEM). His expertise includes the Continental Power System Master Plan, electricity-market design, power-system modelling and planning, renewable energy investment and project development, grid modernisation, climate finance and infrastructure de-risking. He has worked with the African Union Commission, GIZ, the United Nations Development Programme, the World Bank and the African Development Bank, among other partners, on energy programmes and infrastructure initiatives across Africa. He holds a Master of Engineering in Electrical Engineering from Bayero University Kano and is pursuing a PhD in Global Energy Policy at EUCLID University.","id":"shehu-ibrahim-khaleel","photo":"shehu-ibrahim-khaleel.webp","appearances":[{"item":"deep-dive-3","role":"Keynote","component":"partner-sessions"}]},{"name":"Simon Benmarraze","title":"Head of Strategic Infrastructure Unit","org":"IRENA","bio":"Simon Benmarraze is the Senior Manager and Global Head of Energy Planning at the International Renewable Energy Agency (IRENA), based at the Innovation and Technology Centre in Bonn, Germany. With over 15 years of experience in advancing sustainable energy solutions across public and private sectors, he leads IRENA's efforts to translate strategic energy intelligence into actionable policies that accelerate the global transition toward net-zero emissions. Simon is also dedicated to mentoring the next generation of renewable energy professionals and fostering international collaboration for a resilient, inclusive, and sustainable energy future.","photo":"simon-benmarraze.webp","id":"simon-benmarraze","appearances":[{"item":"session-1","role":"Moderator","component":"ltes-forum"}]},{"name":"Sina Makana","title":"Senior Economic Planner","org":"Ministry of Energy, Lesotho","bio":"Sina Makana is a Senior Economic Planner at Lesotho's Ministry of Energy, with experience in project planning, research, project proposal writing and investment briefs for energy projects. She has worked in government and the non-profit sector, planning and managing government- and donor-funded programmes in energy, local government infrastructure and public finance, with skills in analysis, policy analysis and research. A project management professional, she holds a master's degree in economics from Jain University.","id":"sina-makana","photo":"sina-makana.webp","appearances":[{"item":"lunch-d3","role":"Country case","component":"gcep-dialogue"}]},{"name":"Stefan Mager","title":"Head of Infrastructure – Energy, Water, Mobility","org":"Deutsche Gesellschaft für Internationale Zusammenarbeit (GIZ)","bio":"Stefan Mager studied political science in Germany and the United Kingdom. He joined GIZ in 2008 as a project manager for EU Twinning projects in the environmental sector. He has since held different positions within GIZ and was temporarily seconded to KfW and the German Federal Ministry for the Environment. He headed a project advising the Ministry's international department on the global phase-out of fossil fuels, Just Transition, local climate action, decentralised renewable energy and digitalisation. Before becoming head of GIZ's Infrastructure, Energy, Mobility and Water section, he was programme manager in Kosovo, focusing on waste management, circular economy and climate.","id":"stefan-mager","photo":"stefan-mager.webp","appearances":[{"item":"opening","role":"Welcome remarks","component":"ltes-forum"}]},{"name":"Stefanie Bradtner","title":"Communications Manager","org":"GET.transform","id":"stefanie-bradtner","photo":"stefanie-bradtner.webp","appearances":[{"item":"opening","role":"Master of Ceremonies","component":"ltes-forum"}]},{"name":"Dr. Stelios Pesmajoglou","title":"Manager, Mitigation sub-division","org":"UNFCCC","bio":"Dr. Stelios Pesmajoglou is the Manager of the Mitigation sub-division at the UNFCCC secretariat, which deals with mitigation ambition, nationally determined contributions (NDCs), long-term low greenhouse gas emission development strategies (LT-LEDS), sectoral approaches (including energy transition and emissions from international aviation and maritime transport) and the assessment of response measures. Dr. Pesmajoglou has been working on climate change since the mid-1990s and has been involved with the negotiations on the Kyoto Protocol, the Paris Agreement and the ICAO Carbon Offsetting and Reduction Scheme for International Aviation (CORSIA), working for the United Nations, national governments and non-governmental organisations on climate change mitigation and transparency. Dr. Pesmajoglou is an aeronautical engineer with a PhD on the aerodynamics of wind turbines.","id":"stelios-pesmajoglou","photo":"stelios-pesmajoglou.webp","appearances":[{"item":"session-1","role":"Scene-setting speaker","component":"ltes-forum"}]},{"name":"Prof. Dr. Sven Teske","title":"Professor and Research Director, Institute for Sustainable Futures","org":"University of Technology Sydney (UTS), Australia","bio":"Sven Teske is Professor and Research Director at the Institute for Sustainable Futures, University of Technology Sydney (UTS), Australia, where his research focuses on decarbonisation pathways to net zero by 2050 for countries, regions, cities and industry sectors. His work includes technical input to nationally determined contributions (NDCs) for developing countries and analysis of how solar, onshore and offshore wind, and storage are integrated into power grids. He and his team developed the One Earth Climate Model (OECM) series of 1.5°C pathways for the G20 countries and the EU27, broken down by industry sector and presented at COP26 to COP29, and in April 2024 published pathways for Kenya, Rwanda and Tanzania at the IRENA Assembly. With 30 years of experience in renewable energy market and policy analysis, he has authored more than 50 renewable energy reports, including the Global Wind Energy Outlook and REN21's Global Futures Report. He was a lead author of the IPCC Special Report on Renewable Energy Sources and Climate Change Mitigation (2011) and in July 2025 was selected as a lead author for the industry chapter of the IPCC Seventh Assessment Report (Working Group III). He holds a PhD in economics from the University of Flensburg, Germany.","id":"sven-teske","photo":"sven-teske.webp","appearances":[{"item":"session-1","role":"Panellist","component":"ltes-forum"}]},{"name":"Sydney Zimba","title":"Operations Engineer","org":"Southern African Power Pool (SAPP)","id":"sydney-zimba","photo":"","appearances":[{"item":"deep-dive-3","role":"Panellist","component":"partner-sessions"}]},{"name":"Dr. Tania Vorwerk","title":"Deputy Director General, Climate, Environment, Health","org":"Federal Ministry for Economic Cooperation and Development (BMZ), Germany","bio":"Tania Rödiger-Vorwerk is Deputy Director General for Climate, Environment and Health at Germany's Federal Ministry for Economic Cooperation and Development (BMZ). Earlier posts at the ministry include Director for Strategy and Policy Planning and Deputy Director General for Environment and Infrastructure. Dr Rödiger-Vorwerk holds a PhD in European environmental law.","id":"tania-vorwerk","photo":"tania-vorwerk.webp","appearances":[{"item":"opening","role":"Welcome remarks","component":"ltes-forum"}]},{"name":"Thierry Odou","title":"Associate Analyst, Off-Grid Power Systems","org":"IRENA","bio":"Thierry Odou is an energy and climate expert with more than ten years of experience in developing countries. He is Associate Analyst, Off-Grid Power Systems, at IRENA's Innovation and Technology Centre (IITC) in Bonn, where he leads the technical delivery of IRENA's Strategic Energy Access Planning Support (SEAPS) programme, including geospatial energy access planning, scenario development and institutional capacity building with ministries, utilities and rural electrification agencies.","id":"thierry-odou","photo":"thierry-odou.webp","appearances":[{"item":"lunch-d3","role":"Scene-setting speaker","component":"gcep-dialogue"}]},{"name":"Thomas Schmitz","title":"","org":"GIZ","id":"thomas-schmitz","photo":"","appearances":[{"item":"deep-dive-3","role":"Moderator","component":"partner-sessions"}]},{"name":"Toby Couture","title":"Director","org":"E3 Analytics","bio":"Toby Couture is Director of E3 Analytics, an independent renewable energy consultancy based in the Berlin area. He has 20 years of experience working in the renewable energy sector and has advised government policymakers in over 50 countries worldwide on long-term energy planning, de-risking renewable energy investment and power system transformation.","id":"toby-couture","photo":"toby-couture.webp","appearances":[{"item":"session-9","role":"Scene-setting speaker and moderator","component":"implementation"}]},{"name":"Tshering Yangki","title":"Principal Engineer","org":"Department of Energy, Bhutan","bio":"Tshering Yangki is a Principal Engineer with the Department of Energy, Ministry of Energy and Natural Resources, Royal Government of Bhutan, where she has served since 2010. She has been actively involved in energy policy formulation, strategic planning and renewable energy development, and played an important role in formulating Bhutan's Renewable Energy Development Roadmap 2024 and National Energy Policy 2025, which set the strategic direction for the sector, particularly hydropower and solar development towards 2040. Her current work includes the formulation of the Energy Bill, assessment and facilitation of solar project proposals, and research and collaboration with national and international stakeholders. She took a two-year career break to join the Asian Institute of Technology (AIT), Thailand, as a Senior Research Associate, working on energy policy, planning and sustainability. She holds a bachelor's degree in electrical engineering from the College of Science and Technology, Royal University of Bhutan, and a master's degree in energy planning and policy from the University of Technology Sydney, Australia.","id":"tshering-yangki","photo":"tshering-yangki.webp","appearances":[{"item":"lunch-d3","role":"Country case","component":"gcep-dialogue"}]},{"name":"Ubaid Ullah Khan","title":"Specialist, Integrated Energy Planning","org":"Power Planning and Monitoring Company (PPMC), Pakistan","bio":"Ubaid Ullah Khan is a Specialist in Integrated Planning and Economic Analysis at the Integrated Energy Planning (IEP) Secretariat, housed at the Power Planning and Monitoring Company (PPMC), Pakistan. His work focuses on integrated energy planning, energy system modelling, generation expansion planning and energy-sector analysis. He has experience with energy modelling tools including TIMES/VEDA, PLEXOS and Balmorel, and contributes to strengthening Pakistan's integrated energy planning framework.","id":"ubaid-ullah-khan","photo":"ubaid-ullah-khan.webp","appearances":[{"item":"session-10","role":"Presenter","component":"implementation"}]},{"name":"Vanessa Schmidt","title":"","org":"Federal Ministry for Economic Affairs and Energy (BMWE), Germany","id":"vanessa-schmidt","photo":"","appearances":[{"item":"opening","role":"Welcome remarks","component":"ltes-forum"}]},{"name":"Dr. Vivien Foster","title":"Principal Research Fellow, Centre for Environmental Policy","org":"Imperial College London","bio":"Vivien Foster is a Principal Research Fellow at the Centre for Environmental Policy, Imperial College London, where she contributes to postgraduate teaching and supervision, and International Partnerships Lead for the Climate Compatible Growth (CCG) programme. At CCG she leads the team managing its ecosystem of open-source data and modelling tools and its programme of capacity-building opportunities for academics and policymakers in the Global South, in close partnership with a wide range of international organisations. She previously spent more than 20 years at the World Bank in research-oriented leadership roles – most recently as Chief Economist for the Infrastructure Vice-Presidency – and engaged with governments in some 40 countries across Africa, Latin America, Europe, Asia and the Middle East.","id":"vivien-foster","photo":"vivien-foster.webp","appearances":[{"item":"session-6","role":"Moderator","component":"ltes-forum"},{"item":"session-7","role":"Expert perspective","component":"gcep-dialogue"}]},{"name":"Yudiandra Yuwono","title":"Lead Modeller","org":"ASEAN Centre for Energy (ACE)","bio":"Yudiandra Yuwono is Lead Modeller for the ASEAN Energy Outlook at the ASEAN Centre for Energy (ACE), leading work on the 9th ASEAN Energy Outlook (AEO9).","id":"yudiandra-yuwono","photo":"yudiandra-yuwono.webp","appearances":[{"item":"session-3","role":"Panellist","component":"ltes-forum"},{"item":"deep-dive-3","role":"Panellist","component":"partner-sessions"}]},{"name":"Yunshu Li","title":"Energy Systems Analyst, Planning and Economic Studies Section","org":"International Atomic Energy Agency (IAEA)","bio":"Yunshu Li is an Energy Systems Analyst at the International Atomic Energy Agency (IAEA), where she focuses on modelling energy systems and assessing the role of nuclear energy in net-zero transitions. She provides capacity-building training on IAEA modelling tools, such as MESSAGE, to support energy planning teams and modellers. Before joining the Agency, she developed economic models for private companies and international organisations, including Urban Sympheny (Switzerland), the International Renewable Energy Agency (IRENA), Grab (Singapore) and Aurora Energy Research (UK). Her expertise spans regional, national and urban energy supply modelling, power systems, sector coupling and AI applications in energy models. She holds a Master of Engineering from the University of Oxford.","id":"yunshu-li","photo":"yunshu-li.webp","appearances":[{"item":"ai-showcase","role":"Use-case presentation","component":"ltes-forum"}]}]}};
